-- Compare refresh part 4/5 — choose_a/b=text(json), faq=jsonb

-- midjourney-vs-flux
UPDATE comparisons SET choose_a='["✅ You prioritize aesthetic beauty and artistic quality — Midjourney V7 leads for creative visual work", "✅ You want the largest AI art community for prompt sharing, inspiration, and style exploration", "✅ You create photography-style portraits, landscapes, and editorial imagery", "✅ You''re fine with a subscription (Basic $10, Standard $30, Pro $60, Mega $120/month; no free tier) and the Discord + web ecosystem"]', choose_b='["✅ You want top photorealistic quality and accurate prompt adherence — FLUX.2 [pro] and [max] lead here", "✅ You need an API for production use with pay-as-you-go, per-megapixel pricing (no subscriptions or seats)", "✅ You require open-weight models you can run locally or fine-tune — FLUX.2 [dev] and [klein] are open weights", "✅ You generate text within images — FLUX handles typography significantly better than Midjourney"]', faq='[{"q": "Is FLUX better than Midjourney?", "a": "They excel at different things. FLUX.2 [pro] and [max] lead on photorealism, prompt adherence, and text in images, while Midjourney V7 leads on aesthetic quality and artistic style. Choose FLUX for accuracy and realism, Midjourney for artistic beauty."}, {"q": "Can I run FLUX locally?", "a": "Yes. The FLUX.2 [dev] and [klein] variants are open-weight and can be run locally with ComfyUI or similar frontends; [klein] comes in 4B and 9B sizes. The [pro] and [max] variants are API-only. You''ll want a capable GPU for good performance."}, {"q": "Is Midjourney open source?", "a": "No. Midjourney is a closed-source commercial product and its weights are not public. You can only use V7 through the Discord bot or web app. For open-weight alternatives, look at FLUX.2 [dev] and [klein]."}, {"q": "How much does each cost?", "a": "Midjourney is subscription-only: Basic $10, Standard $30, Pro $60, and Mega $120 per month, with no free tier. FLUX.2 is pay-as-you-go by the megapixel — for example, FLUX.2 [pro] API output is $0.03 for the first megapixel then $0.015 per additional megapixel, with no subscriptions or seats."}]'::jsonb WHERE slug='midjourney-vs-flux' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Для вас важнее эстетика и художественное качество — Midjourney V7 лидирует в творческой визуальной работе", "✅ Вам нужно крупнейшее сообщество ИИ-арта для обмена промптами, вдохновения и поиска стилей", "✅ Вы создаёте портреты, пейзажи и редакционные изображения в фотостиле", "✅ Вас устраивает подписка (Basic $10, Standard $30, Pro $60, Mega $120 в месяц; бесплатного тарифа нет) и экосистема Discord + веб"]', choose_b='["✅ Вам нужны максимальная фотореалистичность и точное следование промпту — здесь лидируют FLUX.2 [pro] и [max]", "✅ Вам нужен API для продакшена с оплатой по факту, за мегапиксель (без подписок и мест)", "✅ Вам нужны модели с открытыми весами для локального запуска или дообучения — FLUX.2 [dev] и [klein] открыты", "✅ Вы генерируете текст на изображениях — FLUX справляется с типографикой заметно лучше Midjourney"]', faq='[{"q": "FLUX лучше, чем Midjourney?", "a": "Они сильны в разном. FLUX.2 [pro] и [max] лидируют по фотореализму, точности следования промпту и тексту на изображениях, а Midjourney V7 — по эстетике и художественному стилю. Выбирайте FLUX для точности и реализма, Midjourney — для художественной красоты."}, {"q": "Можно ли запускать FLUX локально?", "a": "Да. Варианты FLUX.2 [dev] и [klein] имеют открытые веса и запускаются локально через ComfyUI и подобные интерфейсы; [klein] доступен в размерах 4B и 9B. Варианты [pro] и [max] доступны только через API. Для хорошей производительности нужен мощный GPU."}, {"q": "Midjourney с открытым исходным кодом?", "a": "Нет. Midjourney — закрытый коммерческий продукт, его веса недоступны публично. Пользоваться V7 можно только через бота в Discord или веб-приложение. В качестве альтернатив с открытыми весами смотрите FLUX.2 [dev] и [klein]."}, {"q": "Сколько стоит каждый?", "a": "Midjourney — только по подписке: Basic $10, Standard $30, Pro $60 и Mega $120 в месяц, без бесплатного тарифа. FLUX.2 — оплата по факту за мегапиксель: например, у FLUX.2 [pro] вывод через API стоит $0,03 за первый мегапиксель и далее $0,015 за каждый дополнительный, без подписок и мест."}]'::jsonb WHERE slug='midjourney-vs-flux' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Priorizas la belleza estética y la calidad artística — Midjourney V7 lidera en trabajo visual creativo", "✅ Quieres la mayor comunidad de arte con IA para compartir prompts, inspirarte y explorar estilos", "✅ Creas retratos, paisajes e imágenes editoriales con estilo fotográfico", "✅ Te vale una suscripción (Basic $10, Standard $30, Pro $60, Mega $120 al mes; sin plan gratuito) y el ecosistema de Discord + web"]', choose_b='["✅ Quieres la mejor calidad fotorrealista y una adherencia precisa al prompt — aquí lideran FLUX.2 [pro] y [max]", "✅ Necesitas una API para producción con pago por uso, por megapíxel (sin suscripciones ni asientos)", "✅ Necesitas modelos de pesos abiertos para ejecutar localmente o ajustar — FLUX.2 [dev] y [klein] son de pesos abiertos", "✅ Generas texto dentro de imágenes — FLUX maneja la tipografía mucho mejor que Midjourney"]', faq='[{"q": "¿Es FLUX mejor que Midjourney?", "a": "Destacan en cosas distintas. FLUX.2 [pro] y [max] lideran en fotorrealismo, fidelidad al prompt y texto en imágenes, mientras que Midjourney V7 lidera en calidad estética y estilo artístico. Elige FLUX para precisión y realismo, Midjourney para belleza artística."}, {"q": "¿Puedo ejecutar FLUX localmente?", "a": "Sí. Las variantes FLUX.2 [dev] y [klein] son de pesos abiertos y se pueden ejecutar localmente con ComfyUI u otras interfaces; [klein] viene en tamaños 4B y 9B. Las variantes [pro] y [max] son solo por API. Conviene una GPU potente para un buen rendimiento."}, {"q": "¿Es Midjourney de código abierto?", "a": "No. Midjourney es un producto comercial de código cerrado y sus pesos no son públicos. Solo puedes usar V7 mediante el bot de Discord o la app web. Como alternativas de pesos abiertos, mira FLUX.2 [dev] y [klein]."}, {"q": "¿Cuánto cuesta cada uno?", "a": "Midjourney es solo por suscripción: Basic $10, Standard $30, Pro $60 y Mega $120 al mes, sin plan gratuito. FLUX.2 es de pago por uso, por megapíxel: por ejemplo, la salida de la API de FLUX.2 [pro] cuesta $0,03 por el primer megapíxel y luego $0,015 por cada megapíxel adicional, sin suscripciones ni asientos."}]'::jsonb WHERE slug='midjourney-vs-flux' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du legst Wert auf ästhetische Schönheit und künstlerische Qualität — Midjourney V7 führt bei kreativer Bildarbeit", "✅ Du willst die größte KI-Kunst-Community zum Teilen von Prompts, für Inspiration und Stilerkundung", "✅ Du erstellst Porträts, Landschaften und redaktionelle Bilder im Fotostil", "✅ Ein Abo ist für dich okay (Basic $10, Standard $30, Pro $60, Mega $120 pro Monat; kein Gratis-Tarif) samt Discord- und Web-Ökosystem"]', choose_b='["✅ Du willst die beste fotorealistische Qualität und präzise Prompt-Treue — hier führen FLUX.2 [pro] und [max]", "✅ Du brauchst eine API für den Produktivbetrieb mit nutzungsbasierter Abrechnung pro Megapixel (keine Abos, keine Seats)", "✅ Du brauchst Open-Weight-Modelle zum lokalen Betrieb oder Finetuning — FLUX.2 [dev] und [klein] sind Open Weights", "✅ Du erzeugst Text in Bildern — FLUX beherrscht Typografie deutlich besser als Midjourney"]', faq='[{"q": "Ist FLUX besser als Midjourney?", "a": "Sie glänzen bei Unterschiedlichem. FLUX.2 [pro] und [max] führen bei Fotorealismus, Prompt-Treue und Text in Bildern, während Midjourney V7 bei ästhetischer Qualität und künstlerischem Stil führt. Wähle FLUX für Genauigkeit und Realismus, Midjourney für künstlerische Schönheit."}, {"q": "Kann ich FLUX lokal ausführen?", "a": "Ja. Die Varianten FLUX.2 [dev] und [klein] sind Open Weights und lassen sich lokal mit ComfyUI oder ähnlichen Frontends betreiben; [klein] gibt es in den Größen 4B und 9B. Die Varianten [pro] und [max] sind nur per API verfügbar. Für gute Leistung empfiehlt sich eine leistungsfähige GPU."}, {"q": "Ist Midjourney Open Source?", "a": "Nein. Midjourney ist ein Closed-Source-Produkt, dessen Gewichte nicht öffentlich sind. V7 lässt sich nur über den Discord-Bot oder die Web-App nutzen. Als Open-Weight-Alternativen bieten sich FLUX.2 [dev] und [klein] an."}, {"q": "Was kostet jeweils?", "a": "Midjourney gibt es nur im Abo: Basic $10, Standard $30, Pro $60 und Mega $120 pro Monat, ohne Gratis-Tarif. FLUX.2 wird nutzungsbasiert pro Megapixel abgerechnet: Die API-Ausgabe von FLUX.2 [pro] kostet z. B. $0,03 für das erste Megapixel und danach $0,015 pro weiterem Megapixel, ohne Abos oder Seats."}]'::jsonb WHERE slug='midjourney-vs-flux' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Для вас важливіші естетика й художня якість — Midjourney V7 лідирує у творчій візуальній роботі", "✅ Вам потрібна найбільша спільнота ШІ-арту для обміну промптами, натхнення та пошуку стилів", "✅ Ви створюєте портрети, пейзажі та редакційні зображення у фотостилі", "✅ Вас влаштовує підписка (Basic $10, Standard $30, Pro $60, Mega $120 на місяць; безкоштовного тарифу немає) та екосистема Discord + веб"]', choose_b='["✅ Вам потрібні максимальна фотореалістичність і точне дотримання промпту — тут лідирують FLUX.2 [pro] і [max]", "✅ Вам потрібен API для продакшену з оплатою за фактом, за мегапіксель (без підписок і місць)", "✅ Вам потрібні моделі з відкритими вагами для локального запуску чи донавчання — FLUX.2 [dev] і [klein] відкриті", "✅ Ви генеруєте текст на зображеннях — FLUX впорається з типографікою помітно краще за Midjourney"]', faq='[{"q": "FLUX кращий за Midjourney?", "a": "Вони сильні в різному. FLUX.2 [pro] і [max] лідирують за фотореалізмом, точністю дотримання промпту й текстом на зображеннях, а Midjourney V7 — за естетикою та художнім стилем. Обирайте FLUX для точності й реалізму, Midjourney — для художньої краси."}, {"q": "Чи можна запускати FLUX локально?", "a": "Так. Варіанти FLUX.2 [dev] і [klein] мають відкриті ваги й запускаються локально через ComfyUI та подібні інтерфейси; [klein] доступний у розмірах 4B і 9B. Варіанти [pro] і [max] доступні лише через API. Для доброї продуктивності знадобиться потужний GPU."}, {"q": "Midjourney з відкритим кодом?", "a": "Ні. Midjourney — закритий комерційний продукт, його ваги недоступні публічно. Користуватися V7 можна лише через бота в Discord або вебдодаток. Як альтернативи з відкритими вагами розгляньте FLUX.2 [dev] і [klein]."}, {"q": "Скільки коштує кожен?", "a": "Midjourney — лише за підпискою: Basic $10, Standard $30, Pro $60 і Mega $120 на місяць, без безкоштовного тарифу. FLUX.2 — оплата за фактом за мегапіксель: наприклад, вивід через API у FLUX.2 [pro] коштує $0,03 за перший мегапіксель і далі $0,015 за кожен додатковий, без підписок і місць."}]'::jsonb WHERE slug='midjourney-vs-flux' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ חשובות לך יופי אסתטי ואיכות אמנותית — Midjourney V7 מובילה בעבודה ויזואלית יצירתית", "✅ אתה רוצה את קהילת אמנות ה-AI הגדולה ביותר לשיתוף פרומפטים, השראה וחקר סגנונות", "✅ אתה יוצר דיוקנאות, נופים ותמונות עריכה בסגנון צילום", "✅ מתאים לך מנוי (Basic $10, Standard $30, Pro $60, Mega $120 לחודש; אין תוכנית חינם) ואקוסיסטם של Discord ווב"]', choose_b='["✅ אתה רוצה את איכות הפוטוריאליזם הטובה ביותר והיצמדות מדויקת לפרומפט — כאן מובילות FLUX.2 [pro] ו-[max]", "✅ אתה צריך API לייצור עם תשלום לפי שימוש, לפי מגה-פיקסל (ללא מנויים או מושבים)", "✅ אתה צריך מודלים במשקלים פתוחים להרצה מקומית או לכיוונון עדין — FLUX.2 [dev] ו-[klein] במשקלים פתוחים", "✅ אתה מייצר טקסט בתוך תמונות — FLUX מטפל בטיפוגרפיה טוב בהרבה מ-Midjourney"]', faq='[{"q": "האם FLUX טוב יותר מ-Midjourney?", "a": "הם מצטיינים בדברים שונים. FLUX.2 [pro] ו-[max] מובילים בפוטוריאליזם, בהיצמדות לפרומפט ובטקסט בתמונות, בעוד Midjourney V7 מובילה באיכות אסתטית ובסגנון אמנותי. בחר FLUX לדיוק וריאליזם, ו-Midjourney ליופי אמנותי."}, {"q": "האם אפשר להריץ את FLUX מקומית?", "a": "כן. הגרסאות FLUX.2 [dev] ו-[klein] הן במשקלים פתוחים וניתן להריץ אותן מקומית עם ComfyUI או ממשקים דומים; [klein] מגיע בגדלים 4B ו-9B. הגרסאות [pro] ו-[max] זמינות רק דרך API. לביצועים טובים כדאי GPU חזק."}, {"q": "האם Midjourney בקוד פתוח?", "a": "לא. Midjourney הוא מוצר מסחרי בקוד סגור, והמשקלים שלו אינם ציבוריים. אפשר להשתמש ב-V7 רק דרך בוט ה-Discord או אפליקציית הווב. כחלופות במשקלים פתוחים, בדוק את FLUX.2 [dev] ו-[klein]."}, {"q": "כמה עולה כל אחד?", "a": "Midjourney הוא במנוי בלבד: Basic $10, Standard $30, Pro $60 ו-Mega $120 לחודש, ללא תוכנית חינם. FLUX.2 הוא בתשלום לפי שימוש, לפי מגה-פיקסל: למשל, פלט ה-API של FLUX.2 [pro] עולה $0.03 עבור המגה-פיקסל הראשון ולאחר מכן $0.015 לכל מגה-פיקסל נוסף, ללא מנויים או מושבים."}]'::jsonb WHERE slug='midjourney-vs-flux' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous privilégiez la beauté esthétique et la qualité artistique — Midjourney V7 excelle pour le travail visuel créatif", "✅ Vous voulez la plus grande communauté d''art IA pour partager des prompts, vous inspirer et explorer des styles", "✅ Vous créez des portraits, paysages et images éditoriales de style photographique", "✅ Un abonnement vous convient (Basic 10 $, Standard 30 $, Pro 60 $, Mega 120 $ par mois ; pas d''offre gratuite) avec l''écosystème Discord + web"]', choose_b='["✅ Vous voulez la meilleure qualité photoréaliste et un respect précis du prompt — FLUX.2 [pro] et [max] mènent ici", "✅ Vous avez besoin d''une API pour la production avec paiement à l''usage, au mégapixel (sans abonnements ni sièges)", "✅ Vous avez besoin de modèles à poids ouverts à exécuter localement ou à affiner — FLUX.2 [dev] et [klein] sont à poids ouverts", "✅ Vous générez du texte dans les images — FLUX gère la typographie bien mieux que Midjourney"]', faq='[{"q": "FLUX est-il meilleur que Midjourney ?", "a": "Ils excellent dans des domaines différents. FLUX.2 [pro] et [max] mènent sur le photoréalisme, le respect du prompt et le texte dans les images, tandis que Midjourney V7 mène sur la qualité esthétique et le style artistique. Choisissez FLUX pour la précision et le réalisme, Midjourney pour la beauté artistique."}, {"q": "Puis-je exécuter FLUX localement ?", "a": "Oui. Les variantes FLUX.2 [dev] et [klein] sont à poids ouverts et s''exécutent localement avec ComfyUI ou d''autres interfaces ; [klein] existe en tailles 4B et 9B. Les variantes [pro] et [max] sont uniquement disponibles via API. Un GPU performant est recommandé pour de bonnes performances."}, {"q": "Midjourney est-il open source ?", "a": "Non. Midjourney est un produit commercial à code fermé et ses poids ne sont pas publics. Vous ne pouvez utiliser V7 que via le bot Discord ou l''application web. Comme alternatives à poids ouverts, regardez FLUX.2 [dev] et [klein]."}, {"q": "Combien coûte chacun ?", "a": "Midjourney est uniquement sur abonnement : Basic 10 $, Standard 30 $, Pro 60 $ et Mega 120 $ par mois, sans offre gratuite. FLUX.2 est à l''usage, au mégapixel : par exemple, la sortie de l''API FLUX.2 [pro] coûte 0,03 $ pour le premier mégapixel puis 0,015 $ par mégapixel supplémentaire, sans abonnements ni sièges."}]'::jsonb WHERE slug='midjourney-vs-flux' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você prioriza beleza estética e qualidade artística — o Midjourney V7 lidera em trabalho visual criativo", "✅ Você quer a maior comunidade de arte com IA para compartilhar prompts, se inspirar e explorar estilos", "✅ Você cria retratos, paisagens e imagens editoriais em estilo fotográfico", "✅ Uma assinatura serve para você (Basic $10, Standard $30, Pro $60, Mega $120 por mês; sem plano gratuito) com o ecossistema Discord + web"]', choose_b='["✅ Você quer a melhor qualidade fotorrealista e aderência precisa ao prompt — aqui lideram o FLUX.2 [pro] e [max]", "✅ Você precisa de uma API para produção com pagamento por uso, por megapixel (sem assinaturas nem assentos)", "✅ Você precisa de modelos de pesos abertos para rodar localmente ou ajustar — FLUX.2 [dev] e [klein] são de pesos abertos", "✅ Você gera texto dentro de imagens — o FLUX lida com tipografia muito melhor que o Midjourney"]', faq='[{"q": "O FLUX é melhor que o Midjourney?", "a": "Eles se destacam em coisas diferentes. FLUX.2 [pro] e [max] lideram em fotorrealismo, aderência ao prompt e texto em imagens, enquanto o Midjourney V7 lidera em qualidade estética e estilo artístico. Escolha o FLUX para precisão e realismo, e o Midjourney para beleza artística."}, {"q": "Posso rodar o FLUX localmente?", "a": "Sim. As variantes FLUX.2 [dev] e [klein] são de pesos abertos e podem ser executadas localmente com ComfyUI ou interfaces semelhantes; o [klein] vem nos tamanhos 4B e 9B. As variantes [pro] e [max] são apenas via API. Uma GPU potente é recomendada para bom desempenho."}, {"q": "O Midjourney é de código aberto?", "a": "Não. O Midjourney é um produto comercial de código fechado e seus pesos não são públicos. Você só pode usar o V7 pelo bot do Discord ou pelo app web. Como alternativas de pesos abertos, veja o FLUX.2 [dev] e [klein]."}, {"q": "Quanto custa cada um?", "a": "O Midjourney é apenas por assinatura: Basic $10, Standard $30, Pro $60 e Mega $120 por mês, sem plano gratuito. O FLUX.2 é pago por uso, por megapixel: por exemplo, a saída da API do FLUX.2 [pro] custa $0,03 pelo primeiro megapixel e depois $0,015 por megapixel adicional, sem assinaturas nem assentos."}]'::jsonb WHERE slug='midjourney-vs-flux' AND lang='pt';

-- midjourney-vs-stable-diffusion
UPDATE comparisons SET choose_a='["✅ You want the best image quality with minimal effort — Midjourney V7 delivers stunning results with no technical setup", "✅ You work in creative fields where visual aesthetics are the primary requirement", "✅ You want the largest AI art community and Discord ecosystem for learning prompts", "✅ You''re fine paying a subscription (from $10/month Basic) for convenience and consistent quality"]', choose_b='["✅ You want free image generation — SD 3.5 is free under the Stability AI Community License for individuals and orgs under $1M annual revenue", "✅ You have a compatible GPU and are comfortable with technical setup (ComfyUI, Automatic1111)", "✅ You need custom fine-tuned models, LoRAs, or ControlNet for specific styles", "✅ You value privacy — images never leave your machine when running locally"]', faq='[{"q": "Is Stable Diffusion better than Midjourney?", "a": "Midjourney V7 consistently produces higher-quality aesthetic output with far less effort. Stable Diffusion 3.5 requires more technical knowledge but offers free local generation, fine-tuning, and full control. For most users who want great images easily, Midjourney wins. For power users who want control and cost-free generation, Stable Diffusion wins."}, {"q": "Is Stable Diffusion free?", "a": "Yes. Stable Diffusion 3.5 model weights are free to download and run locally under the Stability AI Community License, which covers individuals and organizations with under $1M in annual revenue. You need a GPU and software like ComfyUI or Automatic1111. There are no usage fees for local generation."}, {"q": "Can Stable Diffusion match Midjourney quality?", "a": "With the right models (SD 3.5 Large 8.1B), fine-tuning, LoRAs, and prompting skill, Stable Diffusion can produce excellent images. However, Midjourney V7 typically wins on out-of-the-box aesthetic quality with far less effort. Reaching Midjourney-level results with SD requires significant experience."}, {"q": "What is the latest version of Stable Diffusion?", "a": "The current open-weights line is Stable Diffusion 3.5, available as Large (8.1B), Large Turbo, and Medium (2.5B). These models are released by Stability AI under the Community License and can be run locally for free within the license terms."}]'::jsonb WHERE slug='midjourney-vs-stable-diffusion' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Вам нужно лучшее качество изображений с минимумом усилий — Midjourney V7 даёт впечатляющий результат без технической настройки", "✅ Вы работаете в креативных сферах, где визуальная эстетика — главное требование", "✅ Вам важно крупнейшее сообщество AI-арта и экосистема Discord для обучения промптам", "✅ Вы готовы платить подписку (от $10/мес на тарифе Basic) за удобство и стабильное качество"]', choose_b='["✅ Вам нужна бесплатная генерация — SD 3.5 бесплатна по лицензии Stability AI Community для физлиц и организаций с годовым доходом менее $1 млн", "✅ У вас есть подходящий GPU и вы не боитесь технической настройки (ComfyUI, Automatic1111)", "✅ Вам нужны собственные дообученные модели, LoRA или ControlNet для конкретных стилей", "✅ Для вас важна приватность — при локальном запуске изображения не покидают ваш компьютер"]', faq='[{"q": "Stable Diffusion лучше, чем Midjourney?", "a": "Midjourney V7 стабильно выдаёт более качественную эстетику с гораздо меньшими усилиями. Stable Diffusion 3.5 требует больше технических знаний, но даёт бесплатную локальную генерацию, дообучение и полный контроль. Для большинства, кому нужны хорошие изображения без хлопот, побеждает Midjourney. Для продвинутых пользователей, ценящих контроль и бесплатную генерацию, — Stable Diffusion."}, {"q": "Stable Diffusion бесплатна?", "a": "Да. Веса модели Stable Diffusion 3.5 можно бесплатно скачать и запускать локально по лицензии Stability AI Community, которая покрывает физлиц и организации с годовым доходом менее $1 млн. Нужен GPU и ПО вроде ComfyUI или Automatic1111. Плата за локальную генерацию отсутствует."}, {"q": "Может ли Stable Diffusion сравниться по качеству с Midjourney?", "a": "С правильными моделями (SD 3.5 Large 8.1B), дообучением, LoRA и навыком промптинга Stable Diffusion способна выдавать отличные изображения. Но Midjourney V7 обычно выигрывает по эстетике «из коробки» при гораздо меньших усилиях. Достичь уровня Midjourney на SD требует значительного опыта."}, {"q": "Какая последняя версия Stable Diffusion?", "a": "Актуальная линейка с открытыми весами — Stable Diffusion 3.5, доступная в вариантах Large (8.1B), Large Turbo и Medium (2.5B). Эти модели выпущены Stability AI по лицензии Community и могут запускаться локально бесплатно в рамках условий лицензии."}]'::jsonb WHERE slug='midjourney-vs-stable-diffusion' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Quieres la mejor calidad de imagen con el mínimo esfuerzo — Midjourney V7 ofrece resultados impresionantes sin configuración técnica", "✅ Trabajas en campos creativos donde la estética visual es el requisito principal", "✅ Quieres la mayor comunidad de arte con IA y el ecosistema de Discord para aprender prompts", "✅ No te importa pagar una suscripción (desde $10/mes en el plan Basic) por comodidad y calidad constante"]', choose_b='["✅ Quieres generación de imágenes gratuita — SD 3.5 es gratis bajo la Stability AI Community License para individuos y organizaciones con menos de $1M de ingresos anuales", "✅ Tienes una GPU compatible y te sientes cómodo con la configuración técnica (ComfyUI, Automatic1111)", "✅ Necesitas modelos afinados personalizados, LoRAs o ControlNet para estilos específicos", "✅ Valoras la privacidad — las imágenes nunca salen de tu equipo al ejecutarlas localmente"]', faq='[{"q": "¿Es Stable Diffusion mejor que Midjourney?", "a": "Midjourney V7 produce de forma constante una estética de mayor calidad con mucho menos esfuerzo. Stable Diffusion 3.5 requiere más conocimientos técnicos, pero ofrece generación local gratuita, ajuste fino y control total. Para la mayoría que quiere buenas imágenes fácilmente, gana Midjourney. Para usuarios avanzados que quieren control y generación sin coste, gana Stable Diffusion."}, {"q": "¿Es Stable Diffusion gratis?", "a": "Sí. Los pesos de Stable Diffusion 3.5 se pueden descargar y ejecutar localmente de forma gratuita bajo la Stability AI Community License, que cubre a individuos y organizaciones con menos de $1M de ingresos anuales. Necesitas una GPU y software como ComfyUI o Automatic1111. No hay tarifas de uso por la generación local."}, {"q": "¿Puede Stable Diffusion igualar la calidad de Midjourney?", "a": "Con los modelos adecuados (SD 3.5 Large 8.1B), ajuste fino, LoRAs y habilidad con los prompts, Stable Diffusion puede producir imágenes excelentes. Sin embargo, Midjourney V7 suele ganar en calidad estética de fábrica con mucho menos esfuerzo. Alcanzar resultados al nivel de Midjourney con SD requiere experiencia considerable."}, {"q": "¿Cuál es la última versión de Stable Diffusion?", "a": "La línea actual de pesos abiertos es Stable Diffusion 3.5, disponible como Large (8.1B), Large Turbo y Medium (2.5B). Estos modelos son publicados por Stability AI bajo la Community License y pueden ejecutarse localmente de forma gratuita dentro de los términos de la licencia."}]'::jsonb WHERE slug='midjourney-vs-stable-diffusion' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du willst beste Bildqualität mit minimalem Aufwand — Midjourney V7 liefert beeindruckende Ergebnisse ohne technische Einrichtung", "✅ Du arbeitest in kreativen Bereichen, in denen visuelle Ästhetik die Hauptanforderung ist", "✅ Du willst die größte KI-Kunst-Community und das Discord-Ökosystem zum Lernen von Prompts", "✅ Du zahlst gern ein Abo (ab $10/Monat im Basic-Plan) für Komfort und gleichbleibende Qualität"]', choose_b='["✅ Du willst kostenlose Bildgenerierung — SD 3.5 ist unter der Stability AI Community License kostenlos für Einzelpersonen und Organisationen mit unter $1 Mio. Jahresumsatz", "✅ Du hast eine kompatible GPU und kommst mit technischer Einrichtung zurecht (ComfyUI, Automatic1111)", "✅ Du brauchst eigene feinabgestimmte Modelle, LoRAs oder ControlNet für bestimmte Stile", "✅ Dir ist Privatsphäre wichtig — beim lokalen Betrieb verlassen die Bilder nie deinen Rechner"]', faq='[{"q": "Ist Stable Diffusion besser als Midjourney?", "a": "Midjourney V7 liefert durchweg eine hochwertigere Ästhetik mit deutlich weniger Aufwand. Stable Diffusion 3.5 erfordert mehr technisches Wissen, bietet aber kostenlose lokale Generierung, Feintuning und volle Kontrolle. Für die meisten, die einfach gute Bilder wollen, gewinnt Midjourney. Für Power-User, die Kontrolle und kostenfreie Generierung schätzen, gewinnt Stable Diffusion."}, {"q": "Ist Stable Diffusion kostenlos?", "a": "Ja. Die Modellgewichte von Stable Diffusion 3.5 lassen sich kostenlos herunterladen und lokal ausführen — unter der Stability AI Community License, die Einzelpersonen und Organisationen mit unter $1 Mio. Jahresumsatz abdeckt. Du brauchst eine GPU und Software wie ComfyUI oder Automatic1111. Für die lokale Generierung fallen keine Nutzungsgebühren an."}, {"q": "Kann Stable Diffusion mit der Qualität von Midjourney mithalten?", "a": "Mit den richtigen Modellen (SD 3.5 Large 8.1B), Feintuning, LoRAs und Prompting-Können kann Stable Diffusion hervorragende Bilder erzeugen. Midjourney V7 gewinnt jedoch meist bei der ästhetischen Qualität ab Werk mit weit weniger Aufwand. Midjourney-Niveau mit SD zu erreichen erfordert erhebliche Erfahrung."}, {"q": "Was ist die neueste Version von Stable Diffusion?", "a": "Die aktuelle Open-Weights-Reihe ist Stable Diffusion 3.5, verfügbar als Large (8.1B), Large Turbo und Medium (2.5B). Diese Modelle werden von Stability AI unter der Community License veröffentlicht und können im Rahmen der Lizenzbedingungen kostenlos lokal betrieben werden."}]'::jsonb WHERE slug='midjourney-vs-stable-diffusion' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Вам потрібна найкраща якість зображень з мінімумом зусиль — Midjourney V7 дає вражаючий результат без технічного налаштування", "✅ Ви працюєте у креативних сферах, де візуальна естетика — головна вимога", "✅ Вам важлива найбільша спільнота AI-арту та екосистема Discord для навчання промптам", "✅ Ви готові платити підписку (від $10/міс на тарифі Basic) за зручність і стабільну якість"]', choose_b='["✅ Вам потрібна безкоштовна генерація — SD 3.5 безкоштовна за ліцензією Stability AI Community для фізосіб і організацій з річним доходом менше $1 млн", "✅ У вас є сумісний GPU і ви не боїтеся технічного налаштування (ComfyUI, Automatic1111)", "✅ Вам потрібні власні донавчені моделі, LoRA або ControlNet для конкретних стилів", "✅ Для вас важлива приватність — під час локального запуску зображення не залишають ваш комп''ютер"]', faq='[{"q": "Stable Diffusion краща за Midjourney?", "a": "Midjourney V7 стабільно видає якіснішу естетику з набагато меншими зусиллями. Stable Diffusion 3.5 потребує більше технічних знань, але дає безкоштовну локальну генерацію, донавчання й повний контроль. Для більшості, кому потрібні хороші зображення без клопоту, перемагає Midjourney. Для просунутих користувачів, які цінують контроль і безкоштовну генерацію, — Stable Diffusion."}, {"q": "Stable Diffusion безкоштовна?", "a": "Так. Ваги моделі Stable Diffusion 3.5 можна безкоштовно завантажити й запускати локально за ліцензією Stability AI Community, яка охоплює фізосіб і організації з річним доходом менше $1 млн. Потрібен GPU і ПЗ на кшталт ComfyUI або Automatic1111. Плати за локальну генерацію немає."}, {"q": "Чи може Stable Diffusion зрівнятися за якістю з Midjourney?", "a": "З правильними моделями (SD 3.5 Large 8.1B), донавчанням, LoRA та навичкою промптингу Stable Diffusion здатна видавати чудові зображення. Але Midjourney V7 зазвичай виграє за естетикою «з коробки» за значно менших зусиль. Досягти рівня Midjourney на SD потребує вагомого досвіду."}, {"q": "Яка остання версія Stable Diffusion?", "a": "Актуальна лінійка з відкритими вагами — Stable Diffusion 3.5, доступна у варіантах Large (8.1B), Large Turbo та Medium (2.5B). Ці моделі випущені Stability AI за ліцензією Community і можуть запускатися локально безкоштовно в межах умов ліцензії."}]'::jsonb WHERE slug='midjourney-vs-stable-diffusion' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם רוצים את איכות התמונה הטובה ביותר במאמץ מינימלי — Midjourney V7 מספק תוצאות מרהיבות ללא הגדרה טכנית", "✅ אתם עובדים בתחומים יצירתיים שבהם האסתטיקה החזותית היא הדרישה המרכזית", "✅ אתם רוצים את קהילת אמנות ה-AI הגדולה ביותר ואת מערכת ה-Discord ללימוד פרומפטים", "✅ לא אכפת לכם לשלם מנוי (החל מ-$10 לחודש בתוכנית Basic) עבור נוחות ואיכות עקבית"]', choose_b='["✅ אתם רוצים יצירת תמונות חינמית — SD 3.5 חינמי תחת Stability AI Community License עבור יחידים וארגונים עם הכנסה שנתית מתחת ל-$1M", "✅ יש לכם GPU תואם ואתם נוחים עם הגדרה טכנית (ComfyUI, Automatic1111)", "✅ אתם צריכים מודלים מותאמים אישית, LoRAs או ControlNet לסגנונות ספציפיים", "✅ אתם מעריכים פרטיות — התמונות לעולם לא עוזבות את המחשב שלכם בהרצה מקומית"]', faq='[{"q": "האם Stable Diffusion טוב יותר מ-Midjourney?", "a": "Midjourney V7 מפיק באופן עקבי אסתטיקה איכותית יותר במאמץ נמוך בהרבה. Stable Diffusion 3.5 דורש יותר ידע טכני אך מציע יצירה מקומית חינמית, כיוונון עדין ושליטה מלאה. עבור רוב המשתמשים שרוצים תמונות טובות בקלות, Midjourney מנצח. עבור משתמשים מתקדמים שרוצים שליטה ויצירה ללא עלות, Stable Diffusion מנצח."}, {"q": "האם Stable Diffusion חינמי?", "a": "כן. משקלי המודל של Stable Diffusion 3.5 ניתנים להורדה ולהרצה מקומית בחינם תחת Stability AI Community License, המכסה יחידים וארגונים עם הכנסה שנתית מתחת ל-$1M. דרושים GPU ותוכנה כמו ComfyUI או Automatic1111. אין דמי שימוש עבור יצירה מקומית."}, {"q": "האם Stable Diffusion יכול להשתוות לאיכות של Midjourney?", "a": "עם המודלים הנכונים (SD 3.5 Large 8.1B), כיוונון עדין, LoRAs ומיומנות פרומפטים, Stable Diffusion יכול להפיק תמונות מצוינות. עם זאת, Midjourney V7 בדרך כלל מנצח באיכות אסתטית מהקופסה במאמץ נמוך בהרבה. הגעה לרמת Midjourney עם SD דורשת ניסיון משמעותי."}, {"q": "מהי הגרסה האחרונה של Stable Diffusion?", "a": "קו המשקלים הפתוחים הנוכחי הוא Stable Diffusion 3.5, זמין כ-Large ‏(8.1B), ‏Large Turbo ו-Medium ‏(2.5B). מודלים אלה משוחררים על ידי Stability AI תחת Community License וניתן להריצם מקומית בחינם במסגרת תנאי הרישיון."}]'::jsonb WHERE slug='midjourney-vs-stable-diffusion' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous voulez la meilleure qualité d''image avec un minimum d''effort — Midjourney V7 offre des résultats bluffants sans configuration technique", "✅ Vous travaillez dans des domaines créatifs où l''esthétique visuelle est l''exigence principale", "✅ Vous voulez la plus grande communauté d''art IA et l''écosystème Discord pour apprendre les prompts", "✅ Payer un abonnement (à partir de $10/mois avec le plan Basic) pour le confort et une qualité constante ne vous dérange pas"]', choose_b='["✅ Vous voulez une génération d''images gratuite — SD 3.5 est gratuit sous la Stability AI Community License pour les particuliers et les organisations réalisant moins de $1M de chiffre d''affaires annuel", "✅ Vous avez un GPU compatible et êtes à l''aise avec la configuration technique (ComfyUI, Automatic1111)", "✅ Vous avez besoin de modèles affinés personnalisés, de LoRAs ou de ControlNet pour des styles spécifiques", "✅ Vous accordez de l''importance à la confidentialité — les images ne quittent jamais votre machine en exécution locale"]', faq='[{"q": "Stable Diffusion est-il meilleur que Midjourney ?", "a": "Midjourney V7 produit systématiquement une esthétique de meilleure qualité avec beaucoup moins d''effort. Stable Diffusion 3.5 exige davantage de connaissances techniques mais offre une génération locale gratuite, du fine-tuning et un contrôle total. Pour la plupart des utilisateurs qui veulent de belles images facilement, Midjourney l''emporte. Pour les utilisateurs avancés qui veulent du contrôle et une génération sans coût, Stable Diffusion l''emporte."}, {"q": "Stable Diffusion est-il gratuit ?", "a": "Oui. Les poids du modèle Stable Diffusion 3.5 peuvent être téléchargés et exécutés localement gratuitement sous la Stability AI Community License, qui couvre les particuliers et les organisations réalisant moins de $1M de chiffre d''affaires annuel. Il vous faut un GPU et un logiciel comme ComfyUI ou Automatic1111. Aucun frais d''utilisation pour la génération locale."}, {"q": "Stable Diffusion peut-il égaler la qualité de Midjourney ?", "a": "Avec les bons modèles (SD 3.5 Large 8.1B), du fine-tuning, des LoRAs et une bonne maîtrise des prompts, Stable Diffusion peut produire d''excellentes images. Cependant, Midjourney V7 l''emporte généralement sur la qualité esthétique prête à l''emploi avec bien moins d''effort. Atteindre un niveau Midjourney avec SD demande une expérience considérable."}, {"q": "Quelle est la dernière version de Stable Diffusion ?", "a": "La gamme actuelle en poids ouverts est Stable Diffusion 3.5, disponible en Large (8.1B), Large Turbo et Medium (2.5B). Ces modèles sont publiés par Stability AI sous la Community License et peuvent être exécutés localement gratuitement dans le cadre des conditions de la licence."}]'::jsonb WHERE slug='midjourney-vs-stable-diffusion' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você quer a melhor qualidade de imagem com o mínimo de esforço — o Midjourney V7 entrega resultados impressionantes sem configuração técnica", "✅ Você atua em áreas criativas onde a estética visual é o requisito principal", "✅ Você quer a maior comunidade de arte com IA e o ecossistema do Discord para aprender prompts", "✅ Você não se importa em pagar uma assinatura (a partir de $10/mês no plano Basic) por conveniência e qualidade constante"]', choose_b='["✅ Você quer geração de imagens gratuita — o SD 3.5 é gratuito sob a Stability AI Community License para indivíduos e organizações com receita anual abaixo de $1M", "✅ Você tem uma GPU compatível e se sente à vontade com a configuração técnica (ComfyUI, Automatic1111)", "✅ Você precisa de modelos ajustados personalizados, LoRAs ou ControlNet para estilos específicos", "✅ Você valoriza a privacidade — as imagens nunca saem da sua máquina ao rodar localmente"]', faq='[{"q": "O Stable Diffusion é melhor que o Midjourney?", "a": "O Midjourney V7 produz de forma consistente uma estética de maior qualidade com muito menos esforço. O Stable Diffusion 3.5 exige mais conhecimento técnico, mas oferece geração local gratuita, fine-tuning e controle total. Para a maioria que quer boas imagens com facilidade, o Midjourney vence. Para usuários avançados que querem controle e geração sem custo, o Stable Diffusion vence."}, {"q": "O Stable Diffusion é gratuito?", "a": "Sim. Os pesos do modelo Stable Diffusion 3.5 podem ser baixados e executados localmente de graça sob a Stability AI Community License, que cobre indivíduos e organizações com receita anual abaixo de $1M. Você precisa de uma GPU e de software como ComfyUI ou Automatic1111. Não há taxas de uso para a geração local."}, {"q": "O Stable Diffusion consegue igualar a qualidade do Midjourney?", "a": "Com os modelos certos (SD 3.5 Large 8.1B), fine-tuning, LoRAs e habilidade em prompts, o Stable Diffusion pode produzir imagens excelentes. No entanto, o Midjourney V7 costuma vencer na qualidade estética pronta para uso com muito menos esforço. Alcançar o nível do Midjourney com SD exige experiência considerável."}, {"q": "Qual é a versão mais recente do Stable Diffusion?", "a": "A linha atual de pesos abertos é o Stable Diffusion 3.5, disponível como Large (8.1B), Large Turbo e Medium (2.5B). Esses modelos são lançados pela Stability AI sob a Community License e podem ser executados localmente de graça dentro dos termos da licença."}]'::jsonb WHERE slug='midjourney-vs-stable-diffusion' AND lang='pt';

-- mistral-le-chat-vs-chatgpt
UPDATE comparisons SET choose_a='["✅ You''re privacy-conscious and prefer a European AI company subject to GDPR, not US data law", "✅ You want extremely fast responses — Le Chat is built for near-instant, low-latency output", "✅ You want a strong free tier or affordable Pro at $14.99/month for everyday AI tasks", "✅ Data sovereignty matters to your organization — Mistral offers private and on-prem Enterprise deployments"]', choose_b='["✅ You need image generation, voice conversations, data analysis, or web browsing in one assistant", "✅ You want the most feature-complete AI with the largest third-party app and connector ecosystem", "✅ You use AI for complex professional tasks where GPT-5.5''s flagship reasoning matters", "✅ You build on the API — OpenAI''s developer ecosystem is the largest and most mature"]', faq='[{"q": "What is Mistral Le Chat?", "a": "Le Chat is Mistral AI''s conversational assistant, available at mistral.ai. It runs on Mistral''s own frontier models — the current flagship is Mistral Vibe (Medium 3.5). Mistral is a French AI company emphasizing European data sovereignty and open-weight model development."}, {"q": "Is Mistral better than ChatGPT?", "a": "Mistral Vibe is competitive with GPT-5.5 on many benchmarks, and Le Chat is notably faster. ChatGPT offers more features (image generation, voice, data analysis, browsing) and a larger ecosystem. For fast text reasoning and European data handling, Le Chat is a strong alternative."}, {"q": "Is Le Chat free?", "a": "Yes. Le Chat has a Free plan at $0/month with limited features and models. Le Chat Pro is $14.99/month for full model access and higher limits, Team is $24.99/user/month (billed monthly, $50/month minimum, 30GB storage per user), and Enterprise is custom-priced with private deployment."}, {"q": "Are Mistral models open source?", "a": "Mistral releases several models as open weights that anyone can download and run locally, with a strong developer community. Its top frontier models are commercial-only through the Mistral API and Le Chat. ChatGPT''s models (GPT-5.5, GPT-5.6) are closed and API-only."}]'::jsonb WHERE slug='mistral-le-chat-vs-chatgpt' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Вам важна приватность и вы предпочитаете европейскую AI-компанию под GDPR, а не законы США о данных", "✅ Вам нужны предельно быстрые ответы — Le Chat создан для почти мгновенного отклика с низкой задержкой", "✅ Вам подходит щедрый бесплатный тариф или доступный Pro за $14.99/мес для повседневных задач", "✅ Для вашей организации важен суверенитет данных — Mistral предлагает приватные и локальные Enterprise-развёртывания"]', choose_b='["✅ Вам нужны генерация изображений, голосовые беседы, анализ данных и веб-поиск в одном ассистенте", "✅ Вам нужен самый функциональный AI с крупнейшей экосистемой сторонних приложений и коннекторов", "✅ Вы используете AI для сложных профессиональных задач, где важна флагманская логика GPT-5.5", "✅ Вы разрабатываете на API — экосистема разработчиков OpenAI самая большая и зрелая"]', faq='[{"q": "Что такое Mistral Le Chat?", "a": "Le Chat — разговорный ассистент от Mistral AI, доступный на mistral.ai. Он работает на собственных передовых моделях Mistral — текущий флагман Mistral Vibe (Medium 3.5). Mistral — французская AI-компания, делающая упор на европейский суверенитет данных и разработку моделей с открытыми весами."}, {"q": "Mistral лучше ChatGPT?", "a": "Mistral Vibe конкурентоспособна с GPT-5.5 во многих бенчмарках, а Le Chat заметно быстрее. У ChatGPT больше функций (генерация изображений, голос, анализ данных, веб-поиск) и крупнее экосистема. Для быстрых текстовых задач и европейской обработки данных Le Chat — сильная альтернатива."}, {"q": "Le Chat бесплатный?", "a": "Да. У Le Chat есть бесплатный тариф за $0/мес с ограниченным набором функций и моделей. Le Chat Pro стоит $14.99/мес с полным доступом к моделям, Team — $24.99 за пользователя в месяц (помесячная оплата, минимум $50/мес, 30 ГБ на пользователя), а Enterprise — по индивидуальной цене с приватным развёртыванием."}, {"q": "Модели Mistral открытые?", "a": "Mistral выпускает ряд моделей с открытыми весами, которые можно скачать и запускать локально, с сильным сообществом разработчиков. Топовые передовые модели доступны только коммерчески через API Mistral и Le Chat. Модели ChatGPT (GPT-5.5, GPT-5.6) закрытые и доступны только через API."}]'::jsonb WHERE slug='mistral-le-chat-vs-chatgpt' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Te importa la privacidad y prefieres una empresa europea de IA sujeta al RGPD, no a la ley de datos de EE. UU.", "✅ Quieres respuestas muy rápidas — Le Chat está diseñado para una salida casi instantánea y de baja latencia", "✅ Te viene bien un plan gratuito generoso o un Pro asequible de $14.99/mes para tareas cotidianas", "✅ La soberanía de datos importa a tu organización — Mistral ofrece despliegues Enterprise privados y locales"]', choose_b='["✅ Necesitas generación de imágenes, conversaciones por voz, análisis de datos o navegación web en un solo asistente", "✅ Quieres la IA más completa con el mayor ecosistema de aplicaciones y conectores de terceros", "✅ Usas IA para tareas profesionales complejas donde importa el razonamiento insignia de GPT-5.5", "✅ Desarrollas sobre la API — el ecosistema para desarrolladores de OpenAI es el más grande y maduro"]', faq='[{"q": "¿Qué es Mistral Le Chat?", "a": "Le Chat es el asistente conversacional de Mistral AI, disponible en mistral.ai. Funciona con los modelos de frontera propios de Mistral — el buque insignia actual es Mistral Vibe (Medium 3.5). Mistral es una empresa francesa de IA que prioriza la soberanía de datos europea y los modelos de pesos abiertos."}, {"q": "¿Es Mistral mejor que ChatGPT?", "a": "Mistral Vibe compite con GPT-5.5 en muchos benchmarks y Le Chat es notablemente más rápido. ChatGPT ofrece más funciones (generación de imágenes, voz, análisis de datos, navegación) y un ecosistema mayor. Para razonamiento de texto rápido y manejo europeo de datos, Le Chat es una alternativa sólida."}, {"q": "¿Le Chat es gratis?", "a": "Sí. Le Chat tiene un plan gratuito de $0/mes con funciones y modelos limitados. Le Chat Pro cuesta $14.99/mes con acceso completo a modelos, Team cuesta $24.99 por usuario/mes (facturación mensual, mínimo $50/mes, 30 GB por usuario) y Enterprise tiene precio personalizado con despliegue privado."}, {"q": "¿Los modelos de Mistral son de código abierto?", "a": "Mistral publica varios modelos con pesos abiertos que cualquiera puede descargar y ejecutar localmente, con una comunidad de desarrolladores fuerte. Sus modelos de frontera principales son solo comerciales a través de la API de Mistral y Le Chat. Los modelos de ChatGPT (GPT-5.5, GPT-5.6) son cerrados y solo por API."}]'::jsonb WHERE slug='mistral-le-chat-vs-chatgpt' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Datenschutz ist dir wichtig und du bevorzugst ein europäisches KI-Unternehmen unter DSGVO statt US-Datenrecht", "✅ Du willst extrem schnelle Antworten — Le Chat ist auf nahezu sofortige Ausgabe mit geringer Latenz ausgelegt", "✅ Ein großzügiges Gratis-Angebot oder günstiges Pro für $14.99/Monat reicht dir für den Alltag", "✅ Datensouveränität zählt für deine Organisation — Mistral bietet private und On-Prem-Enterprise-Deployments"]', choose_b='["✅ Du brauchst Bildgenerierung, Sprachgespräche, Datenanalyse oder Websuche in einem Assistenten", "✅ Du willst die funktionsreichste KI mit dem größten Ökosystem an Drittanbieter-Apps und Connectors", "✅ Du nutzt KI für komplexe berufliche Aufgaben, bei denen das Flaggschiff-Reasoning von GPT-5.5 zählt", "✅ Du entwickelst auf der API — OpenAIs Entwickler-Ökosystem ist das größte und ausgereifteste"]', faq='[{"q": "Was ist Mistral Le Chat?", "a": "Le Chat ist der Konversationsassistent von Mistral AI, verfügbar auf mistral.ai. Er läuft auf Mistrals eigenen Frontier-Modellen — das aktuelle Flaggschiff ist Mistral Vibe (Medium 3.5). Mistral ist ein französisches KI-Unternehmen mit Fokus auf europäische Datensouveränität und Modelle mit offenen Gewichten."}, {"q": "Ist Mistral besser als ChatGPT?", "a": "Mistral Vibe ist in vielen Benchmarks konkurrenzfähig mit GPT-5.5, und Le Chat ist deutlich schneller. ChatGPT bietet mehr Funktionen (Bildgenerierung, Sprache, Datenanalyse, Websuche) und ein größeres Ökosystem. Für schnelles Text-Reasoning und europäische Datenverarbeitung ist Le Chat eine starke Alternative."}, {"q": "Ist Le Chat kostenlos?", "a": "Ja. Le Chat hat einen Gratis-Tarif für $0/Monat mit eingeschränkten Funktionen und Modellen. Le Chat Pro kostet $14.99/Monat mit vollem Modellzugang, Team kostet $24.99 pro Nutzer/Monat (monatliche Abrechnung, mindestens $50/Monat, 30 GB pro Nutzer) und Enterprise hat individuelle Preise mit privatem Deployment."}, {"q": "Sind Mistral-Modelle Open Source?", "a": "Mistral veröffentlicht mehrere Modelle mit offenen Gewichten, die jeder herunterladen und lokal ausführen kann, mit einer starken Entwickler-Community. Die Top-Frontier-Modelle sind nur kommerziell über die Mistral-API und Le Chat verfügbar. Die ChatGPT-Modelle (GPT-5.5, GPT-5.6) sind geschlossen und nur per API zugänglich."}]'::jsonb WHERE slug='mistral-le-chat-vs-chatgpt' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Вам важлива приватність і ви надаєте перевагу європейській AI-компанії під GDPR, а не законам США про дані", "✅ Вам потрібні гранично швидкі відповіді — Le Chat створений для майже миттєвого відгуку з низькою затримкою", "✅ Вам підходить щедрий безкоштовний тариф або доступний Pro за $14.99/міс для щоденних задач", "✅ Для вашої організації важливий суверенітет даних — Mistral пропонує приватні та локальні Enterprise-розгортання"]', choose_b='["✅ Вам потрібні генерація зображень, голосові розмови, аналіз даних і веб-пошук в одному асистенті", "✅ Вам потрібен найфункціональніший AI з найбільшою екосистемою сторонніх застосунків і конекторів", "✅ Ви використовуєте AI для складних професійних задач, де важлива флагманська логіка GPT-5.5", "✅ Ви розробляєте на API — екосистема розробників OpenAI найбільша та найзріліша"]', faq='[{"q": "Що таке Mistral Le Chat?", "a": "Le Chat — розмовний асистент від Mistral AI, доступний на mistral.ai. Він працює на власних передових моделях Mistral — поточний флагман Mistral Vibe (Medium 3.5). Mistral — французька AI-компанія, що робить акцент на європейському суверенітеті даних і розробці моделей з відкритими вагами."}, {"q": "Mistral кращий за ChatGPT?", "a": "Mistral Vibe конкурентоспроможна з GPT-5.5 у багатьох бенчмарках, а Le Chat помітно швидший. ChatGPT має більше функцій (генерація зображень, голос, аналіз даних, веб-пошук) і більшу екосистему. Для швидких текстових задач та європейської обробки даних Le Chat — сильна альтернатива."}, {"q": "Le Chat безкоштовний?", "a": "Так. У Le Chat є безкоштовний тариф за $0/міс з обмеженим набором функцій і моделей. Le Chat Pro коштує $14.99/міс з повним доступом до моделей, Team — $24.99 за користувача на місяць (щомісячна оплата, мінімум $50/міс, 30 ГБ на користувача), а Enterprise — за індивідуальною ціною з приватним розгортанням."}, {"q": "Моделі Mistral з відкритим кодом?", "a": "Mistral випускає низку моделей з відкритими вагами, які можна завантажити та запускати локально, із сильною спільнотою розробників. Топові передові моделі доступні лише комерційно через API Mistral і Le Chat. Моделі ChatGPT (GPT-5.5, GPT-5.6) закриті й доступні лише через API."}]'::jsonb WHERE slug='mistral-le-chat-vs-chatgpt' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ הפרטיות חשובה לך ואתה מעדיף חברת AI אירופית הכפופה ל-GDPR, ולא לחוקי הנתונים של ארה\"ב", "✅ אתה רוצה תשובות מהירות במיוחד — Le Chat בנוי לפלט כמעט מיידי בהשהיה נמוכה", "✅ מתאים לך מסלול חינמי נדיב או Pro משתלם ב-$14.99 לחודש למשימות יומיומיות", "✅ ריבונות נתונים חשובה לארגון שלך — Mistral מציעה פריסות Enterprise פרטיות ומקומיות"]', choose_b='["✅ אתה צריך יצירת תמונות, שיחות קוליות, ניתוח נתונים או גלישה באינטרנט בעוזר אחד", "✅ אתה רוצה את ה-AI העשיר ביותר בתכונות עם מערכת האפליקציות והמחברים של צד שלישי הגדולה ביותר", "✅ אתה משתמש ב-AI למשימות מקצועיות מורכבות שבהן חשוב חשיבת הדגל של GPT-5.5", "✅ אתה מפתח על ה-API — מערכת המפתחים של OpenAI היא הגדולה והבשלה ביותר"]', faq='[{"q": "מהו Mistral Le Chat?", "a": "Le Chat הוא העוזר השיחתי של Mistral AI, זמין ב-mistral.ai. הוא מופעל על מודלי החזית של Mistral עצמה — הדגל הנוכחי הוא Mistral Vibe (Medium 3.5). Mistral היא חברת AI צרפתית המדגישה ריבונות נתונים אירופית ופיתוח מודלים במשקלים פתוחים."}, {"q": "האם Mistral טוב יותר מ-ChatGPT?", "a": "Mistral Vibe תחרותי מול GPT-5.5 במבחני ביצועים רבים, ו-Le Chat מהיר יותר באופן ניכר. ל-ChatGPT יש יותר תכונות (יצירת תמונות, קול, ניתוח נתונים, גלישה) ומערכת אקולוגית גדולה יותר. לחשיבת טקסט מהירה ולעיבוד נתונים אירופי, Le Chat הוא חלופה חזקה."}, {"q": "האם Le Chat חינמי?", "a": "כן. ל-Le Chat יש מסלול חינמי ב-$0 לחודש עם תכונות ומודלים מוגבלים. Le Chat Pro עולה $14.99 לחודש עם גישה מלאה למודלים, Team עולה $24.99 למשתמש לחודש (חיוב חודשי, מינימום $50 לחודש, 30GB למשתמש), ו-Enterprise במחיר מותאם אישית עם פריסה פרטית."}, {"q": "האם מודלי Mistral בקוד פתוח?", "a": "Mistral משחררת כמה מודלים במשקלים פתוחים שכל אחד יכול להוריד ולהריץ מקומית, עם קהילת מפתחים חזקה. מודלי החזית המובילים שלה זמינים מסחרית בלבד דרך ה-API של Mistral ו-Le Chat. מודלי ChatGPT (GPT-5.5, GPT-5.6) סגורים וזמינים רק דרך API."}]'::jsonb WHERE slug='mistral-le-chat-vs-chatgpt' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous tenez à la confidentialité et préférez une entreprise d''IA européenne soumise au RGPD, pas au droit américain des données", "✅ Vous voulez des réponses extrêmement rapides — Le Chat est conçu pour une sortie quasi instantanée à faible latence", "✅ Un forfait gratuit généreux ou un Pro abordable à 14,99 $/mois vous suffit pour les tâches quotidiennes", "✅ La souveraineté des données compte pour votre organisation — Mistral propose des déploiements Enterprise privés et sur site"]', choose_b='["✅ Vous avez besoin de génération d''images, de conversations vocales, d''analyse de données ou de navigation web dans un seul assistant", "✅ Vous voulez l''IA la plus complète avec le plus grand écosystème d''applications et de connecteurs tiers", "✅ Vous utilisez l''IA pour des tâches professionnelles complexes où le raisonnement phare de GPT-5.5 compte", "✅ Vous développez sur l''API — l''écosystème développeur d''OpenAI est le plus vaste et le plus mature"]', faq='[{"q": "Qu''est-ce que Mistral Le Chat ?", "a": "Le Chat est l''assistant conversationnel de Mistral AI, disponible sur mistral.ai. Il fonctionne avec les modèles de pointe propres à Mistral — le fleuron actuel est Mistral Vibe (Medium 3.5). Mistral est une entreprise française d''IA qui met l''accent sur la souveraineté des données européenne et les modèles à poids ouverts."}, {"q": "Mistral est-il meilleur que ChatGPT ?", "a": "Mistral Vibe rivalise avec GPT-5.5 sur de nombreux benchmarks, et Le Chat est nettement plus rapide. ChatGPT offre plus de fonctionnalités (génération d''images, voix, analyse de données, navigation) et un écosystème plus vaste. Pour un raisonnement textuel rapide et un traitement européen des données, Le Chat est une alternative solide."}, {"q": "Le Chat est-il gratuit ?", "a": "Oui. Le Chat propose un forfait gratuit à 0 $/mois avec fonctionnalités et modèles limités. Le Chat Pro coûte 14,99 $/mois avec accès complet aux modèles, Team coûte 24,99 $/utilisateur/mois (facturation mensuelle, minimum 50 $/mois, 30 Go par utilisateur), et Enterprise a un tarif personnalisé avec déploiement privé."}, {"q": "Les modèles Mistral sont-ils open source ?", "a": "Mistral publie plusieurs modèles à poids ouverts que chacun peut télécharger et exécuter localement, avec une forte communauté de développeurs. Ses meilleurs modèles de pointe sont commerciaux uniquement via l''API Mistral et Le Chat. Les modèles de ChatGPT (GPT-5.5, GPT-5.6) sont fermés et accessibles uniquement par API."}]'::jsonb WHERE slug='mistral-le-chat-vs-chatgpt' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você se preocupa com privacidade e prefere uma empresa de IA europeia sujeita ao RGPD, não à lei de dados dos EUA", "✅ Você quer respostas extremamente rápidas — o Le Chat foi feito para saída quase instantânea e de baixa latência", "✅ Um plano gratuito generoso ou um Pro acessível de $14.99/mês atende suas tarefas do dia a dia", "✅ Soberania de dados importa para sua organização — a Mistral oferece implantações Enterprise privadas e locais"]', choose_b='["✅ Você precisa de geração de imagens, conversas por voz, análise de dados ou navegação na web em um só assistente", "✅ Você quer a IA mais completa em recursos, com o maior ecossistema de aplicativos e conectores de terceiros", "✅ Você usa IA para tarefas profissionais complexas em que o raciocínio de ponta do GPT-5.5 importa", "✅ Você desenvolve na API — o ecossistema de desenvolvedores da OpenAI é o maior e mais maduro"]', faq='[{"q": "O que é o Mistral Le Chat?", "a": "O Le Chat é o assistente de conversação da Mistral AI, disponível em mistral.ai. Ele roda nos modelos de fronteira próprios da Mistral — o carro-chefe atual é o Mistral Vibe (Medium 3.5). A Mistral é uma empresa francesa de IA que enfatiza a soberania de dados europeia e modelos de pesos abertos."}, {"q": "O Mistral é melhor que o ChatGPT?", "a": "O Mistral Vibe compete com o GPT-5.5 em muitos benchmarks, e o Le Chat é notavelmente mais rápido. O ChatGPT oferece mais recursos (geração de imagens, voz, análise de dados, navegação) e um ecossistema maior. Para raciocínio de texto rápido e processamento europeu de dados, o Le Chat é uma alternativa forte."}, {"q": "O Le Chat é gratuito?", "a": "Sim. O Le Chat tem um plano gratuito de $0/mês com recursos e modelos limitados. O Le Chat Pro custa $14.99/mês com acesso total aos modelos, o Team custa $24.99 por usuário/mês (cobrança mensal, mínimo de $50/mês, 30GB por usuário) e o Enterprise tem preço personalizado com implantação privada."}, {"q": "Os modelos da Mistral são de código aberto?", "a": "A Mistral libera vários modelos com pesos abertos que qualquer pessoa pode baixar e executar localmente, com uma comunidade de desenvolvedores forte. Seus principais modelos de fronteira são apenas comerciais via API da Mistral e Le Chat. Os modelos do ChatGPT (GPT-5.5, GPT-5.6) são fechados e acessíveis somente por API."}]'::jsonb WHERE slug='mistral-le-chat-vs-chatgpt' AND lang='pt';

-- perplexity-vs-notebooklm
UPDATE comparisons SET choose_a='["✅ You need answers about current events, recent news, or information updated within days", "✅ You want to search the entire web and get cited, sourced answers with Advanced Deep Research (agentic, powered by Claude Opus 4.5/4.6 on Pro and Max)", "✅ You do broad exploratory research where you don''t have specific documents to upload", "✅ You want a daily AI search engine replacement with multi-model access (GPT-5, Claude, Gemini) that always cites its sources"]', choose_b='["✅ You have specific documents (PDFs, research papers, notes) you want to analyze deeply", "✅ You want AI that works exclusively from your sources — not the open web — now with agentic NotebookLM 2.0 on Gemini 3.5", "✅ You do research synthesis across multiple uploaded documents simultaneously", "✅ You want Audio Overviews that turn your documents into podcast-style conversations"]', faq='[{"q": "What is the difference between Perplexity and NotebookLM?", "a": "Perplexity searches the live web to answer questions, with Advanced Deep Research and multi-model access (GPT-5, Claude, Gemini). NotebookLM only uses documents you upload — it has no web access — and now runs on Gemini 3.5 with the agentic NotebookLM 2.0 upgrade. Perplexity is for questions about the world; NotebookLM is for questions about your specific documents."}, {"q": "Is NotebookLM free?", "a": "Yes. NotebookLM Standard is free for all Google users at notebooklm.google.com. Higher limits come with a Google AI subscription: Plus is $7.99/mo (Google AI Plus), Pro is $19.99/mo (Google AI Pro), and Ultra is $99.99/mo (Google AI Ultra). It is sold only as part of a Google AI plan, not standalone."}, {"q": "Is Perplexity free?", "a": "Perplexity has a free plan with about 5 Pro searches per day. Perplexity Pro is $20/month (or $200/year) and includes ~20 Deep Research runs per day, file uploads, $5/mo Sonar API credits, and access to all available AI models. Max is $200/month (or $2,000/year), and there is a discounted Student/Education Pro at about $10/month."}, {"q": "Is Perplexity better than Google?", "a": "Perplexity is better than Google when you want a direct, cited answer rather than a list of links to read. For navigating to websites, finding local businesses, or general browsing, Google is still better. Perplexity excels for research questions where you want a synthesized, sourced answer."}]'::jsonb WHERE slug='perplexity-vs-notebooklm' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Вам нужны ответы о текущих событиях, свежих новостях или информации, обновлённой за последние дни", "✅ Вы хотите искать по всему вебу и получать ответы с цитатами и источниками через Advanced Deep Research (агентный, работает на Claude Opus 4.5/4.6 в тарифах Pro и Max)", "✅ Вы ведёте широкое исследовательское изучение темы, когда у вас нет конкретных документов для загрузки", "✅ Вам нужна ежедневная замена поисковику с доступом к нескольким моделям (GPT-5, Claude, Gemini), которая всегда указывает источники"]', choose_b='["✅ У вас есть конкретные документы (PDF, научные статьи, заметки), которые вы хотите глубоко проанализировать", "✅ Вам нужен ИИ, работающий исключительно с вашими источниками, а не с открытым вебом — теперь с агентным NotebookLM 2.0 на Gemini 3.5", "✅ Вы делаете синтез исследования сразу по нескольким загруженным документам", "✅ Вам нужны Audio Overviews, превращающие ваши документы в подкаст-разговоры"]', faq='[{"q": "В чём разница между Perplexity и NotebookLM?", "a": "Perplexity ищет ответы в реальном вебе, с Advanced Deep Research и доступом к нескольким моделям (GPT-5, Claude, Gemini). NotebookLM использует только загруженные вами документы — у него нет доступа к вебу — и теперь работает на Gemini 3.5 с агентным обновлением NotebookLM 2.0. Perplexity — для вопросов о мире; NotebookLM — для вопросов о ваших документах."}, {"q": "NotebookLM бесплатен?", "a": "Да. NotebookLM Standard бесплатен для всех пользователей Google на notebooklm.google.com. Повышенные лимиты доступны с подпиской Google AI: Plus — $7.99/мес (Google AI Plus), Pro — $19.99/мес (Google AI Pro), Ultra — $99.99/мес (Google AI Ultra). Продаётся только в составе плана Google AI, отдельно недоступен."}, {"q": "Perplexity бесплатен?", "a": "У Perplexity есть бесплатный план с примерно 5 Pro-поисками в день. Perplexity Pro стоит $20/мес (или $200/год) и включает около 20 запусков Deep Research в день, загрузку файлов, $5/мес кредитов Sonar API и доступ ко всем моделям. Max — $200/мес (или $2000/год), также есть студенческий Pro примерно за $10/мес."}, {"q": "Perplexity лучше Google?", "a": "Perplexity лучше Google, когда нужен прямой ответ с цитатами, а не список ссылок для чтения. Для перехода на сайты, поиска местных заведений или обычного сёрфинга Google всё ещё лучше. Perplexity выигрывает в исследовательских вопросах, где нужен синтезированный ответ с источниками."}]'::jsonb WHERE slug='perplexity-vs-notebooklm' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Necesitas respuestas sobre eventos actuales, noticias recientes o información actualizada en cuestión de días", "✅ Quieres buscar en toda la web y obtener respuestas citadas y con fuentes mediante Advanced Deep Research (agéntico, con Claude Opus 4.5/4.6 en Pro y Max)", "✅ Haces investigación exploratoria amplia cuando no tienes documentos concretos para subir", "✅ Quieres un reemplazo diario del buscador con acceso multimodelo (GPT-5, Claude, Gemini) que siempre cita sus fuentes"]', choose_b='["✅ Tienes documentos concretos (PDF, artículos de investigación, notas) que quieres analizar en profundidad", "✅ Quieres una IA que trabaje exclusivamente con tus fuentes, no con la web abierta — ahora con el agéntico NotebookLM 2.0 sobre Gemini 3.5", "✅ Haces síntesis de investigación a través de varios documentos subidos a la vez", "✅ Quieres Audio Overviews que convierten tus documentos en conversaciones tipo pódcast"]', faq='[{"q": "¿Cuál es la diferencia entre Perplexity y NotebookLM?", "a": "Perplexity busca en la web en vivo para responder, con Advanced Deep Research y acceso multimodelo (GPT-5, Claude, Gemini). NotebookLM solo usa los documentos que subes — no tiene acceso a la web — y ahora funciona sobre Gemini 3.5 con la mejora agéntica NotebookLM 2.0. Perplexity es para preguntas sobre el mundo; NotebookLM, para preguntas sobre tus documentos."}, {"q": "¿NotebookLM es gratis?", "a": "Sí. NotebookLM Standard es gratis para todos los usuarios de Google en notebooklm.google.com. Los límites más altos vienen con una suscripción a Google AI: Plus cuesta 7,99 $/mes (Google AI Plus), Pro 19,99 $/mes (Google AI Pro) y Ultra 99,99 $/mes (Google AI Ultra). Se vende solo como parte de un plan de Google AI, no por separado."}, {"q": "¿Perplexity es gratis?", "a": "Perplexity tiene un plan gratuito con unas 5 búsquedas Pro al día. Perplexity Pro cuesta 20 $/mes (o 200 $/año) e incluye unas 20 ejecuciones de Deep Research al día, subida de archivos, 5 $/mes de créditos de la API Sonar y acceso a todos los modelos. Max cuesta 200 $/mes (o 2000 $/año), y hay un Pro para estudiantes por unos 10 $/mes."}, {"q": "¿Perplexity es mejor que Google?", "a": "Perplexity es mejor que Google cuando quieres una respuesta directa y citada en lugar de una lista de enlaces. Para navegar a webs, encontrar negocios locales o navegar en general, Google sigue siendo mejor. Perplexity destaca en preguntas de investigación donde quieres una respuesta sintetizada y con fuentes."}]'::jsonb WHERE slug='perplexity-vs-notebooklm' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du brauchst Antworten zu aktuellen Ereignissen, neuesten Nachrichten oder Informationen, die innerhalb von Tagen aktualisiert wurden", "✅ Du willst das gesamte Web durchsuchen und zitierte, mit Quellen belegte Antworten per Advanced Deep Research erhalten (agentisch, mit Claude Opus 4.5/4.6 bei Pro und Max)", "✅ Du betreibst breite explorative Recherche, wenn du keine konkreten Dokumente zum Hochladen hast", "✅ Du willst einen täglichen Ersatz für die Suchmaschine mit Multi-Modell-Zugang (GPT-5, Claude, Gemini), der stets seine Quellen nennt"]', choose_b='["✅ Du hast konkrete Dokumente (PDFs, Forschungsarbeiten, Notizen), die du tiefgehend analysieren willst", "✅ Du willst eine KI, die ausschließlich mit deinen Quellen arbeitet — nicht mit dem offenen Web — jetzt mit dem agentischen NotebookLM 2.0 auf Gemini 3.5", "✅ Du erstellst Recherche-Synthesen über mehrere hochgeladene Dokumente gleichzeitig", "✅ Du willst Audio Overviews, die deine Dokumente in podcastartige Gespräche verwandeln"]', faq='[{"q": "Was ist der Unterschied zwischen Perplexity und NotebookLM?", "a": "Perplexity durchsucht das Live-Web, mit Advanced Deep Research und Multi-Modell-Zugang (GPT-5, Claude, Gemini). NotebookLM nutzt nur die Dokumente, die du hochlädst — es hat keinen Web-Zugang — und läuft jetzt auf Gemini 3.5 mit dem agentischen NotebookLM-2.0-Upgrade. Perplexity ist für Fragen über die Welt; NotebookLM für Fragen zu deinen Dokumenten."}, {"q": "Ist NotebookLM kostenlos?", "a": "Ja. NotebookLM Standard ist für alle Google-Nutzer unter notebooklm.google.com kostenlos. Höhere Limits gibt es mit einem Google-AI-Abo: Plus für 7,99 $/Monat (Google AI Plus), Pro für 19,99 $/Monat (Google AI Pro) und Ultra für 99,99 $/Monat (Google AI Ultra). Es wird nur als Teil eines Google-AI-Plans verkauft, nicht einzeln."}, {"q": "Ist Perplexity kostenlos?", "a": "Perplexity hat einen kostenlosen Plan mit etwa 5 Pro-Suchen pro Tag. Perplexity Pro kostet 20 $/Monat (oder 200 $/Jahr) und umfasst rund 20 Deep-Research-Durchläufe pro Tag, Datei-Uploads, 5 $/Monat Sonar-API-Guthaben und Zugang zu allen Modellen. Max kostet 200 $/Monat (oder 2.000 $/Jahr), zudem gibt es ein Studenten-Pro für etwa 10 $/Monat."}, {"q": "Ist Perplexity besser als Google?", "a": "Perplexity ist besser als Google, wenn du eine direkte, mit Quellen belegte Antwort statt einer Linkliste willst. Zum Aufrufen von Websites, Finden lokaler Anbieter oder allgemeinen Surfen ist Google weiterhin besser. Perplexity glänzt bei Recherchefragen, bei denen du eine zusammengefasste, belegte Antwort willst."}]'::jsonb WHERE slug='perplexity-vs-notebooklm' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Вам потрібні відповіді про поточні події, свіжі новини або інформацію, оновлену за останні дні", "✅ Ви хочете шукати по всьому вебу й отримувати відповіді з цитатами та джерелами через Advanced Deep Research (агентний, працює на Claude Opus 4.5/4.6 у тарифах Pro і Max)", "✅ Ви ведете широке дослідницьке вивчення теми, коли немає конкретних документів для завантаження", "✅ Вам потрібна щоденна заміна пошуковику з доступом до кількох моделей (GPT-5, Claude, Gemini), що завжди вказує джерела"]', choose_b='["✅ У вас є конкретні документи (PDF, наукові статті, нотатки), які ви хочете глибоко проаналізувати", "✅ Вам потрібен ШІ, що працює виключно з вашими джерелами, а не з відкритим вебом — тепер з агентним NotebookLM 2.0 на Gemini 3.5", "✅ Ви робите синтез дослідження одразу за кількома завантаженими документами", "✅ Вам потрібні Audio Overviews, що перетворюють ваші документи на подкаст-розмови"]', faq='[{"q": "Яка різниця між Perplexity і NotebookLM?", "a": "Perplexity шукає відповіді в реальному вебі, з Advanced Deep Research і доступом до кількох моделей (GPT-5, Claude, Gemini). NotebookLM використовує лише завантажені вами документи — у нього немає доступу до вебу — і тепер працює на Gemini 3.5 з агентним оновленням NotebookLM 2.0. Perplexity — для запитань про світ; NotebookLM — для запитань про ваші документи."}, {"q": "Чи безкоштовний NotebookLM?", "a": "Так. NotebookLM Standard безкоштовний для всіх користувачів Google на notebooklm.google.com. Вищі ліміти доступні з підпискою Google AI: Plus — $7.99/міс (Google AI Plus), Pro — $19.99/міс (Google AI Pro), Ultra — $99.99/міс (Google AI Ultra). Продається лише у складі плану Google AI, окремо недоступний."}, {"q": "Чи безкоштовний Perplexity?", "a": "Perplexity має безкоштовний план приблизно з 5 Pro-пошуками на день. Perplexity Pro коштує $20/міс (або $200/рік) і включає близько 20 запусків Deep Research на день, завантаження файлів, $5/міс кредитів Sonar API та доступ до всіх моделей. Max — $200/міс (або $2000/рік), також є студентський Pro приблизно за $10/міс."}, {"q": "Чи кращий Perplexity за Google?", "a": "Perplexity кращий за Google, коли потрібна пряма відповідь із цитатами, а не список посилань для читання. Для переходу на сайти, пошуку місцевих закладів чи звичайного серфінгу Google усе ще кращий. Perplexity виграє в дослідницьких запитаннях, де потрібна синтезована відповідь із джерелами."}]'::jsonb WHERE slug='perplexity-vs-notebooklm' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם צריכים תשובות על אירועים אקטואליים, חדשות עדכניות או מידע שהתעדכן בתוך ימים", "✅ אתם רוצים לחפש בכל הרשת ולקבל תשובות מצוטטות עם מקורות באמצעות Advanced Deep Research (סוכני, מבוסס Claude Opus 4.5/4.6 בתוכניות Pro ו-Max)", "✅ אתם עושים מחקר חקרני רחב כאשר אין לכם מסמכים ספציפיים להעלות", "✅ אתם רוצים תחליף יומי למנוע חיפוש עם גישה לכמה מודלים (GPT-5, Claude, Gemini) שתמיד מצטט את המקורות"]', choose_b='["✅ יש לכם מסמכים ספציפיים (PDF, מאמרי מחקר, הערות) שאתם רוצים לנתח לעומק", "✅ אתם רוצים בינה מלאכותית שעובדת אך ורק מהמקורות שלכם — לא מהרשת הפתוחה — כעת עם NotebookLM 2.0 הסוכני על גבי Gemini 3.5", "✅ אתם עושים סינתזת מחקר על פני כמה מסמכים שהועלו בו-זמנית", "✅ אתם רוצים Audio Overviews שהופכים את המסמכים שלכם לשיחות בסגנון פודקאסט"]', faq='[{"q": "מה ההבדל בין Perplexity ל-NotebookLM?", "a": "Perplexity מחפש ברשת החיה כדי לענות, עם Advanced Deep Research וגישה לכמה מודלים (GPT-5, Claude, Gemini). NotebookLM משתמש רק במסמכים שאתם מעלים — אין לו גישה לרשת — וכעת פועל על Gemini 3.5 עם שדרוג NotebookLM 2.0 הסוכני. Perplexity מיועד לשאלות על העולם; NotebookLM לשאלות על המסמכים הספציפיים שלכם."}, {"q": "האם NotebookLM חינמי?", "a": "כן. NotebookLM Standard חינמי לכל משתמשי Google בכתובת notebooklm.google.com. מגבלות גבוהות יותר מגיעות עם מנוי Google AI: Plus בעלות 7.99$ לחודש (Google AI Plus), Pro בעלות 19.99$ לחודש (Google AI Pro) ו-Ultra בעלות 99.99$ לחודש (Google AI Ultra). הוא נמכר רק כחלק מתוכנית Google AI, לא בנפרד."}, {"q": "האם Perplexity חינמי?", "a": "ל-Perplexity יש תוכנית חינמית עם כ-5 חיפושי Pro ביום. Perplexity Pro עולה 20$ לחודש (או 200$ לשנה) וכולל כ-20 הרצות Deep Research ביום, העלאת קבצים, 5$ לחודש קרדיטים ל-Sonar API וגישה לכל המודלים. Max עולה 200$ לחודש (או 2,000$ לשנה), וקיים גם Pro לסטודנטים בכ-10$ לחודש."}, {"q": "האם Perplexity טוב יותר מ-Google?", "a": "Perplexity טוב יותר מ-Google כשאתם רוצים תשובה ישירה ומצוטטת במקום רשימת קישורים לקריאה. לניווט לאתרים, מציאת עסקים מקומיים או גלישה כללית, Google עדיין טוב יותר. Perplexity מצטיין בשאלות מחקר שבהן אתם רוצים תשובה מסונתזת ומגובה במקורות."}]'::jsonb WHERE slug='perplexity-vs-notebooklm' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous avez besoin de réponses sur l''actualité, les dernières nouvelles ou des informations mises à jour en quelques jours", "✅ Vous voulez chercher sur tout le web et obtenir des réponses citées et sourcées via Advanced Deep Research (agentique, propulsé par Claude Opus 4.5/4.6 en Pro et Max)", "✅ Vous menez une recherche exploratoire large lorsque vous n''avez pas de documents précis à téléverser", "✅ Vous voulez un remplacement quotidien du moteur de recherche avec accès multi-modèles (GPT-5, Claude, Gemini) qui cite toujours ses sources"]', choose_b='["✅ Vous avez des documents précis (PDF, articles de recherche, notes) que vous voulez analyser en profondeur", "✅ Vous voulez une IA qui travaille exclusivement à partir de vos sources — pas du web ouvert — désormais avec le NotebookLM 2.0 agentique sur Gemini 3.5", "✅ Vous faites une synthèse de recherche sur plusieurs documents téléversés simultanément", "✅ Vous voulez des Audio Overviews qui transforment vos documents en conversations de type podcast"]', faq='[{"q": "Quelle est la différence entre Perplexity et NotebookLM ?", "a": "Perplexity cherche sur le web en direct pour répondre, avec Advanced Deep Research et un accès multi-modèles (GPT-5, Claude, Gemini). NotebookLM n''utilise que les documents que vous téléversez — il n''a pas d''accès au web — et fonctionne désormais sur Gemini 3.5 avec la mise à niveau agentique NotebookLM 2.0. Perplexity sert aux questions sur le monde ; NotebookLM aux questions sur vos documents."}, {"q": "NotebookLM est-il gratuit ?", "a": "Oui. NotebookLM Standard est gratuit pour tous les utilisateurs Google sur notebooklm.google.com. Des limites plus élevées viennent avec un abonnement Google AI : Plus à 7,99 $/mois (Google AI Plus), Pro à 19,99 $/mois (Google AI Pro) et Ultra à 99,99 $/mois (Google AI Ultra). Il n''est vendu que dans le cadre d''un forfait Google AI, pas séparément."}, {"q": "Perplexity est-il gratuit ?", "a": "Perplexity propose un plan gratuit avec environ 5 recherches Pro par jour. Perplexity Pro coûte 20 $/mois (ou 200 $/an) et inclut environ 20 exécutions de Deep Research par jour, le téléversement de fichiers, 5 $/mois de crédits API Sonar et l''accès à tous les modèles. Max coûte 200 $/mois (ou 2 000 $/an), et il existe un Pro étudiant à environ 10 $/mois."}, {"q": "Perplexity est-il meilleur que Google ?", "a": "Perplexity est meilleur que Google quand vous voulez une réponse directe et sourcée plutôt qu''une liste de liens à lire. Pour naviguer vers des sites, trouver des commerces locaux ou naviguer en général, Google reste meilleur. Perplexity excelle pour les questions de recherche où vous voulez une réponse synthétisée et sourcée."}]'::jsonb WHERE slug='perplexity-vs-notebooklm' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você precisa de respostas sobre eventos atuais, notícias recentes ou informações atualizadas em questão de dias", "✅ Você quer pesquisar em toda a web e obter respostas citadas e com fontes via Advanced Deep Research (agêntico, com Claude Opus 4.5/4.6 nos planos Pro e Max)", "✅ Você faz pesquisa exploratória ampla quando não tem documentos específicos para enviar", "✅ Você quer um substituto diário do buscador com acesso multimodelo (GPT-5, Claude, Gemini) que sempre cita as fontes"]', choose_b='["✅ Você tem documentos específicos (PDFs, artigos de pesquisa, anotações) que quer analisar a fundo", "✅ Você quer uma IA que trabalhe exclusivamente a partir das suas fontes — não da web aberta — agora com o agêntico NotebookLM 2.0 sobre Gemini 3.5", "✅ Você faz síntese de pesquisa em vários documentos enviados ao mesmo tempo", "✅ Você quer Audio Overviews que transformam seus documentos em conversas no estilo podcast"]', faq='[{"q": "Qual é a diferença entre Perplexity e NotebookLM?", "a": "O Perplexity pesquisa na web ao vivo para responder, com Advanced Deep Research e acesso multimodelo (GPT-5, Claude, Gemini). O NotebookLM usa apenas os documentos que você envia — não tem acesso à web — e agora roda sobre o Gemini 3.5 com a atualização agêntica NotebookLM 2.0. O Perplexity é para perguntas sobre o mundo; o NotebookLM, para perguntas sobre os seus documentos."}, {"q": "O NotebookLM é gratuito?", "a": "Sim. O NotebookLM Standard é gratuito para todos os usuários do Google em notebooklm.google.com. Limites maiores vêm com uma assinatura Google AI: Plus por US$ 7,99/mês (Google AI Plus), Pro por US$ 19,99/mês (Google AI Pro) e Ultra por US$ 99,99/mês (Google AI Ultra). É vendido apenas como parte de um plano Google AI, não separadamente."}, {"q": "O Perplexity é gratuito?", "a": "O Perplexity tem um plano gratuito com cerca de 5 buscas Pro por dia. O Perplexity Pro custa US$ 20/mês (ou US$ 200/ano) e inclui cerca de 20 execuções de Deep Research por dia, envio de arquivos, US$ 5/mês em créditos da API Sonar e acesso a todos os modelos. O Max custa US$ 200/mês (ou US$ 2.000/ano), e há um Pro para estudantes por cerca de US$ 10/mês."}, {"q": "O Perplexity é melhor que o Google?", "a": "O Perplexity é melhor que o Google quando você quer uma resposta direta e com fontes em vez de uma lista de links para ler. Para navegar até sites, encontrar negócios locais ou navegar em geral, o Google ainda é melhor. O Perplexity se destaca em perguntas de pesquisa em que você quer uma resposta sintetizada e com fontes."}]'::jsonb WHERE slug='perplexity-vs-notebooklm' AND lang='pt';

-- photomath-vs-duolingo-max
UPDATE comparisons SET choose_a='["✅ You need step-by-step help with math homework — algebra, calculus, geometry, statistics", "✅ You learn best by seeing worked solutions with a clear explanation of each step", "✅ You want to photograph a math problem — handwritten or printed — and get an instant solution", "✅ You''re a student, parent, or teacher who needs a math-specific learning tool, with a genuinely free core app and Photomath Plus at $9.99/month or $69.99/year for deeper explanations"]', choose_b='["✅ You''re learning a new language and want gamified daily practice with GPT-4o-powered AI conversation", "✅ You want Video Call with Lily and Roleplay to practice real-world language scenarios out loud", "✅ You want to understand why an exercise was wrong with clear, AI-generated explanations", "✅ You''re motivated by streaks, XP, and leagues to build a daily language-learning habit"]', faq='[{"q": "What is Photomath?", "a": "Photomath is a math problem solver app. Point your camera at any problem — handwritten or printed — and it instantly returns step-by-step solutions with explanations, covering arithmetic, algebra, trigonometry, calculus, and statistics. The core app is free (no ads, no time limit), and Photomath Plus adds deeper explanations for $9.99/month or $69.99/year."}, {"q": "Is Photomath cheating?", "a": "It depends on how you use it. Using Photomath to check your work or understand where you went wrong is educational; copying answers without following the method is counterproductive. The step-by-step explanations are designed to help you learn, not just supply an answer."}, {"q": "What is Duolingo Max?", "a": "Duolingo Max is the highest Duolingo subscription tier ($29.99/month or $167.99/year). It adds AI features powered by OpenAI''s GPT-4o, including Video Call with the character Lily and Roleplay for practicing real-life conversations, on top of everything in the Super tier."}, {"q": "Is Duolingo Max worth it versus Duolingo Super?", "a": "Duolingo Super ($95.99/year) removes ads and unlocks extra practice. Max ($167.99/year or $29.99/month) adds the GPT-4o Video Call and Roleplay conversation features. If you actively practice speaking with Video Call and Roleplay, Max is worth it; if you mainly do standard exercises, Super is enough."}]'::jsonb WHERE slug='photomath-vs-duolingo-max' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Нужна пошаговая помощь с домашней работой по математике — алгебра, геометрия, тригонометрия, статистика", "✅ Вы лучше усваиваете материал, видя готовое решение с пояснением каждого шага", "✅ Хотите сфотографировать задачу — рукописную или печатную — и мгновенно получить решение", "✅ Вы школьник, родитель или учитель, которому нужен инструмент именно по математике: базовое приложение бесплатно, а Photomath Plus стоит $9.99/мес или $69.99/год за расширенные объяснения"]', choose_b='["✅ Вы изучаете иностранный язык и хотите игровую ежедневную практику с ИИ-диалогами на базе GPT-4o", "✅ Хотите Video Call с персонажем Lily и Roleplay, чтобы вслух отрабатывать реальные жизненные ситуации", "✅ Хотите понимать, почему упражнение выполнено неверно, с понятными объяснениями от ИИ", "✅ Вас мотивируют серии (streak), XP и лиги, чтобы выработать привычку заниматься каждый день"]', faq='[{"q": "Что такое Photomath?", "a": "Photomath — приложение для решения математических задач. Наведите камеру на любую задачу — рукописную или печатную — и мгновенно получите пошаговое решение с объяснениями по арифметике, алгебре, тригонометрии, математическому анализу и статистике. Базовое приложение бесплатно (без рекламы и ограничений по времени), а Photomath Plus добавляет более подробные объяснения за $9.99/мес или $69.99/год."}, {"q": "Photomath — это списывание?", "a": "Всё зависит от того, как вы его используете. Проверять свою работу и разбирать ошибки — это обучение; копировать ответы, не вникая в метод, — контрпродуктивно. Пошаговые объяснения созданы для того, чтобы помочь учиться, а не просто выдать ответ."}, {"q": "Что такое Duolingo Max?", "a": "Duolingo Max — высший тариф подписки Duolingo ($29.99/мес или $167.99/год). Он добавляет функции на базе GPT-4o от OpenAI: Video Call с персонажем Lily и Roleplay для отработки реальных разговоров — в дополнение ко всему, что входит в тариф Super."}, {"q": "Стоит ли Duolingo Max того по сравнению с Duolingo Super?", "a": "Duolingo Super ($95.99/год) убирает рекламу и открывает дополнительную практику. Max ($167.99/год или $29.99/мес) добавляет разговорные функции Video Call и Roleplay на базе GPT-4o. Если вы активно тренируете речь через Video Call и Roleplay — Max оправдан; если делаете в основном стандартные упражнения, достаточно Super."}]'::jsonb WHERE slug='photomath-vs-duolingo-max' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Necesitas ayuda paso a paso con las tareas de matemáticas: álgebra, cálculo, geometría, estadística", "✅ Aprendes mejor viendo soluciones resueltas con una explicación clara de cada paso", "✅ Quieres fotografiar un problema — manuscrito o impreso — y obtener la solución al instante", "✅ Eres estudiante, madre/padre o docente y necesitas una herramienta específica de matemáticas: la app básica es gratuita y Photomath Plus cuesta $9.99/mes o $69.99/año para explicaciones más detalladas"]', choose_b='["✅ Estás aprendiendo un idioma y quieres práctica diaria gamificada con conversación de IA basada en GPT-4o", "✅ Quieres Video Call con el personaje Lily y Roleplay para practicar situaciones reales en voz alta", "✅ Quieres entender por qué fallaste un ejercicio con explicaciones claras generadas por IA", "✅ Te motivan las rachas, los XP y las ligas para crear el hábito de estudiar cada día"]', faq='[{"q": "¿Qué es Photomath?", "a": "Photomath es una app para resolver problemas de matemáticas. Apunta la cámara a cualquier problema — manuscrito o impreso — y obtén al instante soluciones paso a paso con explicaciones de aritmética, álgebra, trigonometría, cálculo y estadística. La app básica es gratuita (sin anuncios ni límite de tiempo) y Photomath Plus añade explicaciones más detalladas por $9.99/mes o $69.99/año."}, {"q": "¿Usar Photomath es hacer trampa?", "a": "Depende de cómo lo uses. Usarlo para revisar tu trabajo o entender dónde te equivocaste es educativo; copiar respuestas sin seguir el método es contraproducente. Las explicaciones paso a paso están pensadas para ayudarte a aprender, no solo para darte la respuesta."}, {"q": "¿Qué es Duolingo Max?", "a": "Duolingo Max es el nivel de suscripción más alto de Duolingo ($29.99/mes o $167.99/año). Añade funciones de IA basadas en GPT-4o de OpenAI, como Video Call con el personaje Lily y Roleplay para practicar conversaciones de la vida real, además de todo lo incluido en el nivel Super."}, {"q": "¿Vale la pena Duolingo Max frente a Duolingo Super?", "a": "Duolingo Super ($95.99/año) elimina los anuncios y desbloquea práctica extra. Max ($167.99/año o $29.99/mes) añade las funciones de conversación Video Call y Roleplay basadas en GPT-4o. Si practicas activamente hablar con Video Call y Roleplay, Max vale la pena; si haces sobre todo ejercicios estándar, Super es suficiente."}]'::jsonb WHERE slug='photomath-vs-duolingo-max' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du brauchst Schritt-für-Schritt-Hilfe bei Mathe-Hausaufgaben — Algebra, Analysis, Geometrie, Statistik", "✅ Du lernst am besten, wenn du ausgearbeitete Lösungen mit einer klaren Erklärung jedes Schritts siehst", "✅ Du willst eine Aufgabe — handschriftlich oder gedruckt — fotografieren und sofort die Lösung erhalten", "✅ Du bist Schüler, Elternteil oder Lehrkraft und brauchst ein reines Mathe-Lernwerkzeug: Die Basis-App ist kostenlos, Photomath Plus kostet $9.99/Monat oder $69.99/Jahr für ausführlichere Erklärungen"]', choose_b='["✅ Du lernst eine neue Sprache und willst spielerische tägliche Übung mit KI-Konversation auf Basis von GPT-4o", "✅ Du willst Video Call mit der Figur Lily und Roleplay, um reale Situationen laut zu üben", "✅ Du willst mit klaren, KI-generierten Erklärungen verstehen, warum eine Übung falsch war", "✅ Dich motivieren Streaks, XP und Ligen, um eine tägliche Lerngewohnheit aufzubauen"]', faq='[{"q": "Was ist Photomath?", "a": "Photomath ist eine App zum Lösen von Matheaufgaben. Richte die Kamera auf eine beliebige Aufgabe — handschriftlich oder gedruckt — und erhalte sofort Schritt-für-Schritt-Lösungen mit Erklärungen zu Arithmetik, Algebra, Trigonometrie, Analysis und Statistik. Die Basis-App ist kostenlos (ohne Werbung, ohne Zeitlimit), und Photomath Plus bietet ausführlichere Erklärungen für $9.99/Monat oder $69.99/Jahr."}, {"q": "Ist Photomath Schummeln?", "a": "Das hängt davon ab, wie du es nutzt. Photomath zu verwenden, um deine Arbeit zu prüfen oder Fehler zu verstehen, ist lehrreich; Antworten abzuschreiben, ohne den Rechenweg nachzuvollziehen, ist kontraproduktiv. Die Schritt-für-Schritt-Erklärungen sollen dir beim Lernen helfen, nicht nur eine Antwort liefern."}, {"q": "Was ist Duolingo Max?", "a": "Duolingo Max ist die höchste Duolingo-Abostufe ($29.99/Monat oder $167.99/Jahr). Sie ergänzt KI-Funktionen auf Basis von OpenAIs GPT-4o, darunter Video Call mit der Figur Lily und Roleplay zum Üben realer Gespräche — zusätzlich zu allem, was in der Super-Stufe enthalten ist."}, {"q": "Lohnt sich Duolingo Max gegenüber Duolingo Super?", "a": "Duolingo Super ($95.99/Jahr) entfernt Werbung und schaltet zusätzliche Übungen frei. Max ($167.99/Jahr oder $29.99/Monat) ergänzt die GPT-4o-Gesprächsfunktionen Video Call und Roleplay. Wenn du aktiv das Sprechen mit Video Call und Roleplay übst, lohnt sich Max; wenn du hauptsächlich Standardübungen machst, reicht Super."}]'::jsonb WHERE slug='photomath-vs-duolingo-max' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Потрібна покрокова допомога з домашкою з математики — алгебра, геометрія, тригонометрія, статистика", "✅ Ви краще засвоюєте матеріал, коли бачите готове розв''язання з поясненням кожного кроку", "✅ Хочете сфотографувати задачу — рукописну чи друковану — і миттєво отримати розв''язання", "✅ Ви учень, батьки або вчитель, яким потрібен інструмент саме з математики: базовий застосунок безкоштовний, а Photomath Plus коштує $9.99/міс або $69.99/рік за розширені пояснення"]', choose_b='["✅ Ви вивчаєте іноземну мову й хочете ігрову щоденну практику з ШІ-діалогами на основі GPT-4o", "✅ Хочете Video Call з персонажем Lily і Roleplay, щоб уголос відпрацьовувати реальні життєві ситуації", "✅ Хочете розуміти, чому вправу виконано неправильно, з чіткими поясненнями від ШІ", "✅ Вас мотивують серії (streak), XP і ліги, щоб виробити звичку займатися щодня"]', faq='[{"q": "Що таке Photomath?", "a": "Photomath — застосунок для розв''язання математичних задач. Наведіть камеру на будь-яку задачу — рукописну чи друковану — і миттєво отримайте покрокове розв''язання з поясненнями з арифметики, алгебри, тригонометрії, математичного аналізу та статистики. Базовий застосунок безкоштовний (без реклами й обмежень у часі), а Photomath Plus додає докладніші пояснення за $9.99/міс або $69.99/рік."}, {"q": "Photomath — це списування?", "a": "Усе залежить від того, як ви його використовуєте. Перевіряти свою роботу й розбирати помилки — це навчання; копіювати відповіді, не вникаючи в метод, — контрпродуктивно. Покрокові пояснення створені, щоб допомогти вчитися, а не просто видати відповідь."}, {"q": "Що таке Duolingo Max?", "a": "Duolingo Max — найвищий тариф підписки Duolingo ($29.99/міс або $167.99/рік). Він додає функції на основі GPT-4o від OpenAI: Video Call з персонажем Lily і Roleplay для відпрацювання реальних розмов — на додачу до всього, що входить у тариф Super."}, {"q": "Чи вартий Duolingo Max того порівняно з Duolingo Super?", "a": "Duolingo Super ($95.99/рік) прибирає рекламу й відкриває додаткову практику. Max ($167.99/рік або $29.99/міс) додає розмовні функції Video Call і Roleplay на основі GPT-4o. Якщо ви активно тренуєте мовлення через Video Call і Roleplay — Max виправданий; якщо робите переважно стандартні вправи, достатньо Super."}]'::jsonb WHERE slug='photomath-vs-duolingo-max' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם צריכים עזרה שלב-אחר-שלב בשיעורי הבית במתמטיקה — אלגברה, חשבון דיפרנציאלי ואינטגרלי, גאומטריה, סטטיסטיקה", "✅ אתם לומדים הכי טוב כשרואים פתרונות מלאים עם הסבר ברור לכל שלב", "✅ אתם רוצים לצלם תרגיל — בכתב יד או מודפס — ולקבל פתרון מיידי", "✅ אתם תלמידים, הורים או מורים שזקוקים לכלי ייעודי למתמטיקה: האפליקציה הבסיסית חינמית, ו-Photomath Plus עולה $9.99 לחודש או $69.99 לשנה עבור הסברים מעמיקים יותר"]', choose_b='["✅ אתם לומדים שפה חדשה ורוצים תרגול יומי מגומיפיי עם שיחת AI מבוססת GPT-4o", "✅ אתם רוצים Video Call עם הדמות Lily ו-Roleplay כדי לתרגל בקול תרחישים מהחיים האמיתיים", "✅ אתם רוצים להבין למה טעיתם בתרגיל, עם הסברים ברורים שנוצרים על ידי AI", "✅ אתם מונעים מרצפי ימים (streak), XP וליגות כדי לבנות הרגל לימוד יומי"]', faq='[{"q": "מה זה Photomath?", "a": "Photomath היא אפליקציה לפתרון תרגילי מתמטיקה. כוונו את המצלמה לכל תרגיל — בכתב יד או מודפס — וקבלו מיד פתרונות שלב-אחר-שלב עם הסברים באריתמטיקה, אלגברה, טריגונומטריה, חשבון דיפרנציאלי ואינטגרלי וסטטיסטיקה. האפליקציה הבסיסית חינמית (ללא פרסומות וללא הגבלת זמן), ו-Photomath Plus מוסיפה הסברים מעמיקים יותר תמורת $9.99 לחודש או $69.99 לשנה."}, {"q": "האם Photomath זו רמאות?", "a": "זה תלוי איך משתמשים בה. שימוש ב-Photomath כדי לבדוק את העבודה שלכם או להבין היכן טעיתם הוא לימודי; העתקת תשובות בלי לעקוב אחרי השיטה היא לא יעילה. ההסברים שלב-אחר-שלב נועדו לעזור לכם ללמוד, לא רק לספק תשובה."}, {"q": "מה זה Duolingo Max?", "a": "Duolingo Max הוא מסלול המנוי הגבוה ביותר של Duolingo ($29.99 לחודש או $167.99 לשנה). הוא מוסיף יכולות AI מבוססות GPT-4o של OpenAI, כולל Video Call עם הדמות Lily ו-Roleplay לתרגול שיחות מהחיים האמיתיים — בנוסף לכל מה שכלול במסלול Super."}, {"q": "האם Duolingo Max שווה את זה לעומת Duolingo Super?", "a": "Duolingo Super ($95.99 לשנה) מסיר פרסומות ופותח תרגול נוסף. Max ($167.99 לשנה או $29.99 לחודש) מוסיף את יכולות השיחה Video Call ו-Roleplay מבוססות GPT-4o. אם אתם מתרגלים דיבור באופן פעיל עם Video Call ו-Roleplay, Max שווה את זה; אם אתם עושים בעיקר תרגילים רגילים, Super מספיק."}]'::jsonb WHERE slug='photomath-vs-duolingo-max' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous avez besoin d''une aide pas à pas pour les devoirs de maths — algèbre, analyse, géométrie, statistiques", "✅ Vous apprenez mieux en voyant des solutions détaillées avec une explication claire de chaque étape", "✅ Vous voulez photographier un problème — manuscrit ou imprimé — et obtenir la solution instantanément", "✅ Vous êtes élève, parent ou enseignant et cherchez un outil dédié aux maths : l''app de base est gratuite et Photomath Plus coûte $9.99/mois ou $69.99/an pour des explications plus détaillées"]', choose_b='["✅ Vous apprenez une nouvelle langue et voulez une pratique quotidienne ludique avec une conversation IA basée sur GPT-4o", "✅ Vous voulez Video Call avec le personnage Lily et Roleplay pour pratiquer à voix haute des scénarios réels", "✅ Vous voulez comprendre pourquoi un exercice était faux grâce à des explications claires générées par l''IA", "✅ Vous êtes motivé par les séries (streaks), les XP et les ligues pour créer une habitude d''apprentissage quotidienne"]', faq='[{"q": "Qu''est-ce que Photomath ?", "a": "Photomath est une application de résolution de problèmes de maths. Pointez la caméra sur n''importe quel problème — manuscrit ou imprimé — et obtenez instantanément des solutions pas à pas avec explications, en arithmétique, algèbre, trigonométrie, analyse et statistiques. L''app de base est gratuite (sans publicité ni limite de temps) et Photomath Plus ajoute des explications plus détaillées pour $9.99/mois ou $69.99/an."}, {"q": "Photomath, est-ce tricher ?", "a": "Cela dépend de l''usage. Utiliser Photomath pour vérifier votre travail ou comprendre vos erreurs est pédagogique ; copier les réponses sans suivre la méthode est contre-productif. Les explications pas à pas sont conçues pour vous aider à apprendre, pas seulement à fournir une réponse."}, {"q": "Qu''est-ce que Duolingo Max ?", "a": "Duolingo Max est le niveau d''abonnement le plus élevé de Duolingo ($29.99/mois ou $167.99/an). Il ajoute des fonctionnalités IA basées sur GPT-4o d''OpenAI, dont Video Call avec le personnage Lily et Roleplay pour pratiquer des conversations réelles — en plus de tout ce qu''inclut le niveau Super."}, {"q": "Duolingo Max en vaut-il la peine face à Duolingo Super ?", "a": "Duolingo Super ($95.99/an) supprime les publicités et débloque des exercices supplémentaires. Max ($167.99/an ou $29.99/mois) ajoute les fonctionnalités de conversation Video Call et Roleplay basées sur GPT-4o. Si vous pratiquez activement l''oral avec Video Call et Roleplay, Max en vaut la peine ; si vous faites surtout des exercices classiques, Super suffit."}]'::jsonb WHERE slug='photomath-vs-duolingo-max' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você precisa de ajuda passo a passo com a lição de matemática — álgebra, cálculo, geometria, estatística", "✅ Você aprende melhor vendo soluções resolvidas com uma explicação clara de cada passo", "✅ Você quer fotografar um problema — manuscrito ou impresso — e obter a solução na hora", "✅ Você é estudante, pai/mãe ou professor e precisa de uma ferramenta específica de matemática: o app básico é gratuito e o Photomath Plus custa $9.99/mês ou $69.99/ano para explicações mais detalhadas"]', choose_b='["✅ Você está aprendendo um novo idioma e quer prática diária gamificada com conversação de IA baseada em GPT-4o", "✅ Você quer Video Call com a personagem Lily e Roleplay para praticar em voz alta situações reais", "✅ Você quer entender por que errou um exercício, com explicações claras geradas por IA", "✅ Você se motiva com sequências (streaks), XP e ligas para criar o hábito de estudar todo dia"]', faq='[{"q": "O que é o Photomath?", "a": "O Photomath é um app para resolver problemas de matemática. Aponte a câmera para qualquer problema — manuscrito ou impresso — e receba na hora soluções passo a passo com explicações de aritmética, álgebra, trigonometria, cálculo e estatística. O app básico é gratuito (sem anúncios e sem limite de tempo), e o Photomath Plus adiciona explicações mais detalhadas por $9.99/mês ou $69.99/ano."}, {"q": "Usar o Photomath é colar?", "a": "Depende de como você usa. Usar o Photomath para conferir seu trabalho ou entender onde errou é educativo; copiar respostas sem acompanhar o método é contraproducente. As explicações passo a passo foram feitas para ajudar você a aprender, não apenas para dar uma resposta."}, {"q": "O que é o Duolingo Max?", "a": "O Duolingo Max é o nível de assinatura mais alto do Duolingo ($29.99/mês ou $167.99/ano). Ele adiciona recursos de IA baseados no GPT-4o da OpenAI, incluindo o Video Call com a personagem Lily e o Roleplay para praticar conversas da vida real — além de tudo o que está incluído no nível Super."}, {"q": "O Duolingo Max vale a pena em comparação com o Duolingo Super?", "a": "O Duolingo Super ($95.99/ano) remove os anúncios e libera prática extra. O Max ($167.99/ano ou $29.99/mês) adiciona os recursos de conversação Video Call e Roleplay baseados em GPT-4o. Se você pratica ativamente a fala com o Video Call e o Roleplay, o Max vale a pena; se faz principalmente exercícios padrão, o Super é suficiente."}]'::jsonb WHERE slug='photomath-vs-duolingo-max' AND lang='pt';
